	S.TopDownYaw = 0.f;
	S.TopDownPitch = -55.f;
	S.TopDownDistance = 2000.f;
	S.TopDownFov = 50.f;
	S.ShoulderDistance = 400.f;
	S.ShoulderHeight = 160.f;
	S.ShoulderSide = 60.f;
	S.ShoulderFov = 80.f;
	S.EyeHeight = 150.f;
	S.FirstPersonFov = 90.f;
	S.MinPitch = -60.f;
	S.MaxPitch = 45.f;
	S.MouseSensitivity = 1.f;
