IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamCameraTopDownTest, "Jam.Camera.TopDownLooksAtTheHero", JamTest::Flags)

bool FJamCameraTopDownTest::RunTest(const FString& Parameters)
