3	FJamView JamCameraRules::ViewFor(
4		EJamCameraMode Mode, const FVector& HeroPos, float LookYaw, float LookPitch, const FJamCameraSettings& Settings)
5	{
6		FJamView View;
7		switch (Mode)
8		{
9			case EJamCameraMode::TopDown:
10				View.Rotation = FRotator(Settings.TopDownPitch, Settings.TopDownYaw, 0.0);
11				View.Location = HeroPos - View.Rotation.Vector() * Settings.TopDownDistance;
12				View.Fov = Settings.TopDownFov;
13				break;
14			case EJamCameraMode::Shoulder:
15			{
16				View.Rotation = FRotator(LookPitch, LookYaw, 0.0);
17				const FVector Pivot = HeroPos + FVector(0.0, 0.0, Settings.ShoulderHeight);
18				const FVector Right = FRotationMatrix(FRotator(0.0, LookYaw, 0.0)).GetUnitAxis(EAxis::Y);
19				View.Location = Pivot - View.Rotation.Vector() * Settings.ShoulderDistance + Right * Settings.ShoulderSide;
20				View.Fov = Settings.ShoulderFov;
21				break;
22			}
23			case EJamCameraMode::FirstPerson:
24				View.Rotation = FRotator(LookPitch, LookYaw, 0.0);
25				View.Location = HeroPos + FVector(0.0, 0.0, Settings.EyeHeight);
26				View.Fov = Settings.FirstPersonFov;
27				break;
28		}
29		return View;
30	}
