#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "GameFramework/PlayerController.h"
#include "View/JamCameraRules.h"

#include "JamPlayerController.generated.h"

class AJamCameraRig;

/**
 * The player's hands: turns the keyboard and the mouse into the hero's intent and switches the camera. The player has no
 * pawn, the hero is a body of the simulation.
 *
 * Keys are polled on purpose. The prototype has a dozen fixed keys and no rebinding, so input assets would only be one
 * more thing to cook.
 */
UCLASS()
class JAMGAME_API AJamPlayerController : public APlayerController
{
	GENERATED_BODY()

public:
	AJamPlayerController();

	/** Reads this frame's input: may switch the camera, turns the look, returns what the hero wants to do. */
	FJamIntent ReadIntent(AJamCameraRig& Rig, const FJamFighter& Hero);

	/** Switches the camera and the mouse behaviour that goes with it (a cursor in top-down, mouse look otherwise). */
	void UseCamera(AJamCameraRig& Rig, EJamCameraMode Mode, const FJamFighter& Hero);

private:
	/** The last known aim: kept while the cursor ray misses the arena. */
	FJamAim Aim;
};

#pragma once

#include "CoreMinimal.h"

#include "JamCameraRules.generated.h"

/**
 * Numbers of the three candidate cameras. The values live in the [JamCamera] section of Config/DefaultGame.ini, one line
 * per field. Angles in degrees, distances in cm.
 */
USTRUCT()
struct JAMGAME_API FJamCameraSettings
{
	GENERATED_BODY()

	/** Top-down 3/4: a fixed direction, the camera only follows the hero. */
	UPROPERTY()
	float TopDownYaw = 0.f;

	UPROPERTY()
	float TopDownPitch = 0.f;

	UPROPERTY()
	float TopDownDistance = 0.f;

	UPROPERTY()
	float TopDownFov = 0.f;

	/** Third person: behind the hero, above and to the right of him. */
	UPROPERTY()
	float ShoulderDistance = 0.f;

	UPROPERTY()
	float ShoulderHeight = 0.f;

	UPROPERTY()
	float ShoulderSide = 0.f;

	UPROPERTY()
	float ShoulderFov = 0.f;

	/** First person. */
	UPROPERTY()
	float EyeHeight = 0.f;

	UPROPERTY()
	float FirstPersonFov = 0.f;

	/** Limits of looking down and up in the mouse-look cameras. */
	UPROPERTY()
	float MinPitch = 0.f;

	UPROPERTY()
	float MaxPitch = 0.f;

	/** Degrees of turn per unit of mouse movement. */
	UPROPERTY()
	float MouseSensitivity = 0.f;
};

/** The three cameras the prototype is judged in, on F1, F2 and F3. */
enum class EJamCameraMode : uint8
{
	TopDown,
	Shoulder,
	FirstPerson
};

struct FJamView
{
	FVector Location = FVector::ZeroVector;
	FRotator Rotation = FRotator::ZeroRotator;
	float Fov = 90.f;
};

/**
 * Where each camera stands. The camera is presentation only: the simulation gets a move direction and an aim and never
 * learns which mode produced them.
 * Tests: Jam.Camera.*
 */
namespace JamCameraRules
{
/** Section with the camera numbers (FJamCameraSettings). */
inline const TCHAR* const Section = TEXT("JamCamera");

/** HeroPos is the hero's feet in the world. The look angles matter only in the mouse-look modes. */
JAMGAME_API FJamView ViewFor(
	EJamCameraMode Mode, const FVector& HeroPos, float LookYaw, float LookPitch, const FJamCameraSettings& Settings);

/** Yaw that "forward" on the keyboard means in this mode: the screen's up in top-down, the look direction otherwise. */
JAMGAME_API float MoveBasisYaw(EJamCameraMode Mode, float LookYaw, const FJamCameraSettings& Settings);

JAMGAME_API float ClampPitch(float Pitch, const FJamCameraSettings& Settings);
} // namespace JamCameraRules

#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "View/JamCameraRules.h"

#include "JamCameraRig.generated.h"

class UCameraComponent;

/**
 * The game camera: one actor that stands where JamCameraRules puts it for the current mode. It owns the mode and the look
 * angles of the mouse-look modes; the player controller writes into it and asks it how to turn the move input.
 */
UCLASS()
class JAMGAME_API AJamCameraRig : public AActor
{
	GENERATED_BODY()

public:
	AJamCameraRig();

	virtual void PostInitializeComponents() override;

	void SetMode(EJamCameraMode InMode) { Mode = InMode; }

	EJamCameraMode GetMode() const { return Mode; }

	/** Mouse movement of the frame, in the units of the player input. */
	void AddLook(float MouseX, float MouseY);

	/** Points the look along a yaw, level with the ground: used when a mouse-look mode is entered. */
	void SetLook(float Yaw);

	float GetLookYaw() const { return LookYaw; }

	/** Yaw that "forward" on the keyboard means now. */
	float GetMoveBasisYaw() const;

	/** Places the camera for the hero's feet at HeroPos. Called every frame after the views are placed. */
	void Sync(const FVector& HeroPos);

private:
	UPROPERTY()
	TObjectPtr<UCameraComponent> Camera;

	FJamCameraSettings Settings;
	EJamCameraMode Mode = EJamCameraMode::TopDown;
	float LookYaw = 0.f;
	float LookPitch = 0.f;
};

#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "Subsystems/WorldSubsystem.h"

#include "JamFightSubsystem.generated.h"

/**
 * Host of the fight simulation in a game world: holds the state and the balance numbers and runs the fixed steps.
 *
 * It does not tick by itself. The game mode calls Advance once per frame after it has written the intents, so the order
 * inside a frame is always input, simulation, view. Everything else only reads from here.
 */
UCLASS()
class JAMGAME_API UJamFightSubsystem : public UWorldSubsystem
{
	GENERATED_BODY()

public:
	virtual void Initialize(FSubsystemCollectionBase& Collection) override;

	/** Starts the fight over with the numbers from the ini. */
	void Restart();

	/** Runs the fixed steps that fit into the frame. */
	void Advance(float FrameDt);

	const FJamFight& GetFight() const { return Fight; }

	const FJamBalanceData& GetBalance() const { return Balance; }

	/** How far the frame is between the last two steps, 0 to 1: the views interpolate with it. */
	float GetAlpha() const { return Alpha; }

	/** Events of every step run by the last Advance. */
	const TArray<FJamEvent>& GetFrameEvents() const { return FrameEvents; }

	/** What the fighters want. Written by the player controller and the boss brain before Advance. */
	FJamIntents Intents;

protected:
	virtual bool DoesSupportWorldType(const EWorldType::Type WorldType) const override;

private:
	FJamBalanceData Balance;
	FJamFight Fight;
	float Accumulated = 0.f;
	float Alpha = 1.f;
	TArray<FJamEvent> FrameEvents;
};

#pragma once

#include "CoreMinimal.h"
#include "Math/RandomStream.h"

/**
 * Plain data of the fight simulation.
 *
 * The fight is flat: simulation X and Y are world X and Y, height exists only in the view. Nothing here knows about
 * actors, cameras or input devices: the hero and the boss are driven by the same FJamIntent, whoever writes it.
 */

enum class EJamSide : uint8
{
	Hero,
	Boss
};

/** The fixed step of the simulation. Every duration inside the simulation is a whole number of steps. */
namespace JamSim
{
inline constexpr int32 StepsPerSecond = 60;
inline constexpr float StepDt = 1.f / StepsPerSecond;

/** Seconds from the balance data as steps, at least one. */
inline int32 Ticks(float Seconds)
{
	return FMath::Max(1, FMath::RoundToInt32(Seconds * StepsPerSecond));
}

inline EJamSide Other(EJamSide Side)
{
	return Side == EJamSide::Hero ? EJamSide::Boss : EJamSide::Hero;
}
} // namespace JamSim

/** One value for the hero and one for the boss. */
template <typename T>
struct TJamPerSide
{
	T Items[2];

	T& operator[](EJamSide Side) { return Items[static_cast<int32>(Side)]; }

	const T& operator[](EJamSide Side) const { return Items[static_cast<int32>(Side)]; }
};

/** Where a fighter aims. A zero Dir means "no aim this step": the fighter keeps its facing. */
struct FJamAim
{
	FVector2D Dir = FVector2D::ZeroVector;
	FVector2D Point = FVector2D::ZeroVector;
};

/** What a fighter wants to do this step. Buttons are "held" states, the simulation decides when they fire. */
struct FJamIntent
{
	/** World-space move direction, length up to 1. */
	FVector2D Move = FVector2D::ZeroVector;
	FJamAim Aim;
	bool bPrimary = false;
	bool bSecondary = false;
	bool bDash = false;
	/** Index of the picked option of the steal choice, -1 when nothing is picked. */
	int32 Choice = -1;
};

using FJamIntents = TJamPerSide<FJamIntent>;

struct FJamFighter
{
	FVector2D Pos = FVector2D::ZeroVector;
	/** Position before the last step, for the view to interpolate from. */
	FVector2D PrevPos = FVector2D::ZeroVector;
	FVector2D Facing = FVector2D(1.0, 0.0);
	float Radius = 0.f;
	float Speed = 0.f;
	float Health = 0.f;
	float MaxHealth = 0.f;
	/** First step on which the ball can be shot again. */
	int32 BallReadyTick = 0;
};

enum class EJamProjectile : uint8
{
	Ball,
	Shuriken,
	Memo
};

struct FJamProjectile
{
	int32 Id = 0;
	EJamProjectile Kind = EJamProjectile::Ball;
	EJamSide Owner = EJamSide::Hero;
	FVector2D Pos = FVector2D::ZeroVector;
	FVector2D PrevPos = FVector2D::ZeroVector;
	FVector2D Vel = FVector2D::ZeroVector;
	float Radius = 0.f;
	float Damage = 0.f;
	/** Step on which it disappears on its own. */
	int32 DieTick = 0;
	bool bExplosive = false;
};

enum class EJamEvent : uint8
{
	ProjectileSpawned,
	ProjectileGone,
	Hit
};

/** Something the view, the sound and the tests may want to know about a step. */
struct FJamEvent
{
	EJamEvent Type = EJamEvent::Hit;
	/** Who shot (ProjectileSpawned) or who was hit (Hit). */
	EJamSide Side = EJamSide::Hero;
	int32 ProjectileId = 0;
	FVector2D Pos = FVector2D::ZeroVector;
	float Amount = 0.f;
};

/** The whole state of a fight. Copying it is a snapshot. */
struct FJamFight
{
	int32 Tick = 0;
	TJamPerSide<FJamFighter> Fighters;
	TArray<FJamProjectile> Projectiles;
	int32 NextId = 1;
	/** Events of the last step only. */
	TArray<FJamEvent> Events;
	/** The only source of randomness of the simulation. */
	FRandomStream Stream;
};

