#include "Game/JamGameMode.h"

#include "Game/JamPlayerController.h"
#include "Sim/JamFightSubsystem.h"
#include "UI/JamHUD.h"
#include "View/JamArenaView.h"
#include "View/JamCameraRig.h"
#include "View/JamFighterView.h"
#include "View/JamProjectilesView.h"

namespace
{
const FLinearColor HeroBeanColor(0.1f, 0.75f, 1.0f);
const FLinearColor BossBeanColor(0.75f, 0.1f, 0.12f);

const TCHAR* CameraName(EJamCameraMode Mode)
{
	switch (Mode)
	{
		case EJamCameraMode::TopDown:
			return TEXT("top-down");
		case EJamCameraMode::Shoulder:
			return TEXT("shoulder");
		default:
			return TEXT("first person");
	}
}
} // namespace

AJamGameMode::AJamGameMode()
{
	PrimaryActorTick.bCanEverTick = true;
	PlayerControllerClass = AJamPlayerController::StaticClass();
	HUDClass = AJamHUD::StaticClass();
	DefaultPawnClass = nullptr;
}

void AJamGameMode::RestartPlayer(AController* NewPlayer)
{
}

void AJamGameMode::StartPlay()
{
	Super::StartPlay();
	UWorld* World = GetWorld();
	const UJamFightSubsystem* Host = World->GetSubsystem<UJamFightSubsystem>();
	if (!Host)
	{
		return;
	}
	const FJamFight& Fight = Host->GetFight();
	Arena = World->SpawnActor<AJamArenaView>();
	Arena->Init(Host->GetBalance().ArenaRadius);
	HeroView = World->SpawnActor<AJamFighterView>();
	HeroView->Init(Fight.Fighters[EJamSide::Hero].Radius, HeroBeanColor);
	BossView = World->SpawnActor<AJamFighterView>();
	BossView->Init(Fight.Fighters[EJamSide::Boss].Radius, BossBeanColor);
	Projectiles = World->SpawnActor<AJamProjectilesView>();
	Rig = World->SpawnActor<AJamCameraRig>();
}

void AJamGameMode::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
	AJamPlayerController* Player = Cast<AJamPlayerController>(GetWorld()->GetFirstPlayerController());
	if (!Host || !Player || !Rig)
	{
		return;
	}
	const FJamFighter& Hero = Host->GetFight().Fighters[EJamSide::Hero];
	if (!bPlayerReady)
	{
		// The controller ticks first, so the keys read here are this frame's keys.
		AddTickPrerequisiteActor(Player);
		Player->SetViewTarget(Rig);
		Player->UseCamera(*Rig, EJamCameraMode::TopDown, Hero);
		bPlayerReady = true;
	}

	Host->Intents[EJamSide::Hero] = Player->ReadIntent(*Rig, Hero);
	Host->Advance(DeltaSeconds);

	const float Alpha = Host->GetAlpha();
	HeroView->Sync(Hero, Alpha);
	BossView->Sync(Host->GetFight().Fighters[EJamSide::Boss], Alpha);
	Projectiles->Sync(Host->GetFight().Projectiles, Alpha);
	Rig->Sync(HeroView->GetActorLocation());

	const bool bFirstPerson = Rig->GetMode() == EJamCameraMode::FirstPerson;
	HeroView->SetActorHiddenInGame(bFirstPerson);
	if (AJamHUD* Hud = Cast<AJamHUD>(Player->GetHUD()))
	{
		Hud->bCrosshair = Rig->GetMode() != EJamCameraMode::TopDown;
		Hud->CameraLabel = CameraName(Rig->GetMode());
	}
}
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"

#include "JamGameMode.generated.h"

class AJamArenaView;
class AJamCameraRig;
class AJamFighterView;
class AJamProjectilesView;

/**
 * Conductor of a frame: reads the player's intent, advances the simulation, then places the views and the camera, always
 * in this order. It also builds the scene, since the map is empty.
 */
UCLASS()
class JAMGAME_API AJamGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	AJamGameMode();

	virtual void StartPlay() override;
	virtual void Tick(float DeltaSeconds) override;

	/** The player has no pawn: the hero is a body of the simulation. */
	virtual void RestartPlayer(AController* NewPlayer) override;

private:
	UPROPERTY()
	TObjectPtr<AJamArenaView> Arena;

	UPROPERTY()
	TObjectPtr<AJamFighterView> HeroView;

	UPROPERTY()
	TObjectPtr<AJamFighterView> BossView;

	UPROPERTY()
	TObjectPtr<AJamProjectilesView> Projectiles;

	UPROPERTY()
	TObjectPtr<AJamCameraRig> Rig;

	/** True once the player controller is wired to the camera. */
	bool bPlayerReady = false;
};
#include "Game/JamPlayerController.h"

#include "Sim/JamAimRules.h"
#include "Sim/JamMoveRules.h"
#include "View/JamCameraRig.h"

namespace
{
// How far ahead of the hero the aim point of the mouse-look cameras is. Aimed abilities land there at most.
constexpr float LookAimReach = 600.f;
} // namespace

AJamPlayerController::AJamPlayerController()
{
	bAutoManageActiveCameraTarget = false;
}

void AJamPlayerController::UseCamera(AJamCameraRig& Rig, EJamCameraMode Mode, const FJamFighter& Hero)
{
	Rig.SetMode(Mode);
	if (Mode == EJamCameraMode::TopDown)
	{
		FInputModeGameAndUI InputMode;
		InputMode.SetLockMouseToViewportBehavior(EMouseLockMode::LockAlways);
		InputMode.SetHideCursorDuringCapture(false);
		SetInputMode(InputMode);
		SetShowMouseCursor(true);
		return;
	}
	// The look starts where the hero already faces, so the switch does not turn him.
	Rig.SetLook(FMath::RadiansToDegrees(FMath::Atan2(Hero.Facing.Y, Hero.Facing.X)));
	SetInputMode(FInputModeGameOnly());
	SetShowMouseCursor(false);
}

FJamIntent AJamPlayerController::ReadIntent(AJamCameraRig& Rig, const FJamFighter& Hero)
{
	if (WasInputKeyJustPressed(EKeys::F1))
	{
		UseCamera(Rig, EJamCameraMode::TopDown, Hero);
	}
	else if (WasInputKeyJustPressed(EKeys::F2))
	{
		UseCamera(Rig, EJamCameraMode::Shoulder, Hero);
	}
	else if (WasInputKeyJustPressed(EKeys::F3))
	{
		UseCamera(Rig, EJamCameraMode::FirstPerson, Hero);
	}

	if (Rig.GetMode() == EJamCameraMode::TopDown)
	{
		FVector Origin;
		FVector Direction;
