// Distance the demo bot keeps from the boss.
constexpr float DemoRange = 700.f;
// Time on each camera before the demo moves to the next one.
constexpr float DemoCameraSeconds = 8.f;
constexpr double CaptureFps = 30.0;

EJamCameraMode DemoCamera(float Time)
{
	const EJamCameraMode Modes[] = {EJamCameraMode::TopDown, EJamCameraMode::Shoulder, EJamCameraMode::FirstPerson};
	return Modes[FMath::FloorToInt32(Time / DemoCameraSeconds) % UE_ARRAY_COUNT(Modes)];
}
} // namespace

void FJamDemo::Init()
{
	const TCHAR* CommandLine = FCommandLine::Get();
	bOn = FParse::Param(CommandLine, TEXT("JamDemo"));
	FParse::Value(CommandLine, TEXT("JamDemoSeconds="), QuitAfter);
	if (FParse::Value(CommandLine, TEXT("JamCapture="), CaptureDir))
	{
		// A fixed step makes the saved frames an even 30 per second however long a frame takes to save.
		FApp::SetFixedDeltaTime(1.0 / CaptureFps);
		FApp::SetUseFixedTimeStep(true);
	}
}

FJamIntent FJamDemo::Drive(const FJamFight& Fight, AJamPlayerController& Player, AJamCameraRig& Rig, float Time)
{
	const FJamIntent Intent = JamBotRules::Kite(Fight, EJamSide::Hero, DemoRange);
	const EJamCameraMode Mode = DemoCamera(Time);
	if (Rig.GetMode() != Mode)
	{
		Player.UseCamera(Rig, Mode, Fight.Fighters[EJamSide::Hero]);
	}
	if (Mode != EJamCameraMode::TopDown)
	{
		Rig.SetLook(FMath::RadiansToDegrees(FMath::Atan2(Intent.Aim.Dir.Y, Intent.Aim.Dir.X)));
	}
	return Intent;
}

void FJamDemo::EndFrame(float Time)
{
	if (!CaptureDir.IsEmpty())
	{
		FScreenshotRequest::RequestScreenshot(CaptureDir / FString::Printf(TEXT("f_%05d.png"), Frame++), true, false);
	}
	if (QuitAfter > 0.f && Time >= QuitAfter)
	{
		RequestEngineExit(TEXT("The demo run is over"));
	}
}

