#include "UI/JamHUD.h"

#include "Engine/Canvas.h"
#include "Engine/Engine.h"
#include "Sim/JamFightSubsystem.h"

namespace
{
// Layout of the prototype HUD as fractions of the screen: presentation only, replaced by Kirill's UI in block E.
constexpr float BossBarWidth = 0.5f;
constexpr float BossBarTop = 0.04f;
constexpr float HeroBarWidth = 0.22f;
constexpr float HeroBarBottom = 0.93f;
constexpr float BarHeight = 0.022f;
constexpr float HudMargin = 0.03f;
constexpr float CrosshairSize = 4.f;
constexpr float TextScale = 1.4f;
const FLinearColor BarBackColor(0.f, 0.f, 0.f, 0.6f);
const FLinearColor BossBarColor(0.9f, 0.15f, 0.15f);
const FLinearColor HeroBarColor(0.2f, 0.9f, 1.0f);
} // namespace

void AJamHUD::DrawBar(float X, float Y, float Width, float Height, float Fraction, const FLinearColor& Color)
{
	DrawRect(BarBackColor, X, Y, Width, Height);
	DrawRect(Color, X, Y, Width * FMath::Clamp(Fraction, 0.f, 1.f), Height);
}

void AJamHUD::DrawHUD()
{
	Super::DrawHUD();
	const UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
	if (!Canvas || !Host)
	{
		return;
	}
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	UFont* Font = GEngine->GetMediumFont();
	const FJamFighter& Hero = Host->GetFight().Fighters[EJamSide::Hero];
	const FJamFighter& Boss = Host->GetFight().Fighters[EJamSide::Boss];

	const float BossX = 0.5f * (1.f - BossBarWidth) * W;
	DrawBar(BossX, BossBarTop * H, BossBarWidth * W, BarHeight * H, Boss.Health / FMath::Max(1.f, Boss.MaxHealth), BossBarColor);
	const FString BossText =
		FString::Printf(TEXT("THE PUBLISHER  %d / %d"), FMath::CeilToInt32(Boss.Health), FMath::CeilToInt32(Boss.MaxHealth));
	DrawText(BossText, FLinearColor::White, BossX, (BossBarTop + BarHeight) * H + 4.f, Font, TextScale);

	DrawBar(HudMargin * W, HeroBarBottom * H, HeroBarWidth * W, BarHeight * H, Hero.Health / FMath::Max(1.f, Hero.MaxHealth), HeroBarColor);
	const FString HeroText = FString::Printf(TEXT("RONIN  %d"), FMath::CeilToInt32(Hero.Health));
	DrawText(HeroText, FLinearColor::White, HudMargin * W, HeroBarBottom * H - 28.f, Font, TextScale);

	const FString CameraText = FString::Printf(TEXT("Camera: %s    F1 top-down   F2 shoulder   F3 first person"), *CameraLabel);
	DrawText(CameraText, FLinearColor::White, HudMargin * W, HudMargin * H, Font, 1.f);

	if (bCrosshair)
	{
		DrawRect(FLinearColor::White, 0.5f * W - 0.5f * CrosshairSize, 0.5f * H - 0.5f * CrosshairSize, CrosshairSize, CrosshairSize);
	}
}
#include "View/JamArenaView.h"

#include "Components/DirectionalLightComponent.h"
#include "Components/SkyAtmosphereComponent.h"
#include "Components/SkyLightComponent.h"
#include "Components/StaticMeshComponent.h"
#include "View/JamShapes.h"

namespace
{
// Greybox look of the arena: presentation only, replaced by the art in block E.
constexpr float FloorThickness = 20.f;
constexpr int32 PostCount = 16;
constexpr float PostWidth = 60.f;
constexpr float PostHeight = 400.f;
const FLinearColor FloorColor(0.08f, 0.09f, 0.12f);
const FLinearColor PostColorA(0.0f, 0.8f, 1.0f);
const FLinearColor PostColorB(1.0f, 0.1f, 0.6f);
const FRotator SunRotation(-50.0, -35.0, 0.0);
} // namespace

AJamArenaView::AJamArenaView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));

	Floor = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Floor"));
	Floor->SetupAttachment(RootComponent);
	JamShapes::Setup(*Floor, JamShapes::Cylinder());
	// The posts are made in Init: the cube has to be found here, in a constructor.
	JamShapes::Cube();

	Sun = CreateDefaultSubobject<UDirectionalLightComponent>(TEXT("Sun"));
	Sun->SetupAttachment(RootComponent);
	Sun->SetMobility(EComponentMobility::Movable);
	Sun->SetRelativeRotation(SunRotation);

	Atmosphere = CreateDefaultSubobject<USkyAtmosphereComponent>(TEXT("Atmosphere"));
	Atmosphere->SetupAttachment(RootComponent);

	SkyLight = CreateDefaultSubobject<USkyLightComponent>(TEXT("SkyLight"));
	SkyLight->SetupAttachment(RootComponent);
	SkyLight->SetMobility(EComponentMobility::Movable);
	SkyLight->SetRealTimeCapture(true);
}

void AJamArenaView::Init(float ArenaRadius)
{
	const float Diameter = 2.f * ArenaRadius / JamShapes::UnitSize;
	Floor->SetRelativeScale3D(FVector(Diameter, Diameter, FloorThickness / JamShapes::UnitSize));
	Floor->SetRelativeLocation(FVector(0.0, 0.0, -0.5 * FloorThickness));
	JamShapes::Paint(*Floor, FloorColor);

	for (int32 Index = Posts.Num(); Index < PostCount; ++Index)
	{
		UStaticMeshComponent* Post = NewObject<UStaticMeshComponent>(this);
		JamShapes::Setup(*Post, JamShapes::Cube());
		Post->SetupAttachment(RootComponent);
		Post->RegisterComponent();
		Posts.Add(Post);
	}
	for (int32 Index = 0; Index < Posts.Num(); ++Index)
	{
		const float Angle = UE_TWO_PI * Index / Posts.Num();
		const FVector Location(ArenaRadius * FMath::Cos(Angle), ArenaRadius * FMath::Sin(Angle), 0.5f * PostHeight);
		Posts[Index]->SetRelativeLocation(Location);
		Posts[Index]->SetRelativeRotation(FRotator(0.0, FMath::RadiansToDegrees(Angle), 0.0));
		Posts[Index]->SetRelativeScale3D(FVector(PostWidth, PostWidth, PostHeight) / JamShapes::UnitSize);
		JamShapes::Paint(*Posts[Index], Index % 2 == 0 ? PostColorA : PostColorB);
	}
}
#pragma once

