#include "Sim/JamFightRules.h"

#include "Sim/JamHealthRules.h"
#include "Sim/JamMoveRules.h"
#include "Sim/JamProjectileRules.h"

namespace
{
// Where the fighters start, as fractions of the arena radius along X: the hero looks at the boss across the centre.
constexpr float HeroStartX = -0.5f;
constexpr float BossStartX = 0.3f;

FJamFighter MakeFighter(float X, float FacingX, float Radius, float Speed, float Health)
{
	FJamFighter Fighter;
	Fighter.Pos = Fighter.PrevPos = FVector2D(X, 0.0);
	Fighter.Facing = FVector2D(FacingX, 0.0);
	Fighter.Radius = Radius;
	Fighter.Speed = Speed;
	Fighter.Health = Fighter.MaxHealth = Health;
	return Fighter;
}

void AddEvent(FJamFight& Fight, EJamEvent Type, EJamSide Side, int32 ProjectileId, const FVector2D& Pos, float Amount)
{
	FJamEvent Event;
	Event.Type = Type;
	Event.Side = Side;
	Event.ProjectileId = ProjectileId;
	Event.Pos = Pos;
	Event.Amount = Amount;
	Fight.Events.Add(Event);
}

void MoveFighter(FJamFight& Fight, EJamSide Side, const FJamIntent& Intent, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	const FJamFighter& Other = Fight.Fighters[JamSim::Other(Side)];
	Self.PrevPos = Self.Pos;
	if (!Intent.Aim.Dir.IsNearlyZero())
	{
		Self.Facing = Intent.Aim.Dir.GetSafeNormal();
	}
	const FVector2D Velocity = JamMoveRules::Velocity(Intent.Move, Self.Speed);
	if (Velocity.IsNearlyZero())
	{
		// A fighter that stands is never nudged, whoever walks into it.
		return;
	}
	FVector2D Pos = Self.Pos + Velocity * JamSim::StepDt;
	Pos = JamMoveRules::PushOut(Pos, Self.Radius, Other.Pos, Other.Radius);
	Self.Pos = JamMoveRules::ClampToArena(Pos, Self.Radius, Balance.ArenaRadius);
}

void AdvanceProjectiles(FJamFight& Fight, const FJamBalanceData& Balance)
{
	for (int32 Index = Fight.Projectiles.Num() - 1; Index >= 0; --Index)
	{
		FJamProjectile& Projectile = Fight.Projectiles[Index];
		Projectile.PrevPos = Projectile.Pos;
		Projectile.Pos += Projectile.Vel * JamSim::StepDt;
		const EJamSide TargetSide = JamSim::Other(Projectile.Owner);
		FJamFighter& Target = Fight.Fighters[TargetSide];
		if (JamProjectileRules::SweepHitsCircle(Projectile.PrevPos, Projectile.Pos, Projectile.Radius, Target.Pos, Target.Radius))
		{
			Target.Health = JamHealthRules::Apply(Target.Health, Projectile.Damage, false);
			AddEvent(Fight, EJamEvent::Hit, TargetSide, Projectile.Id, Projectile.Pos, Projectile.Damage);
			Fight.Projectiles.RemoveAtSwap(Index);
		}
		else if (JamProjectileRules::IsGone(Projectile, Fight.Tick, Balance.ArenaRadius))
		{
			AddEvent(Fight, EJamEvent::ProjectileGone, Projectile.Owner, Projectile.Id, Projectile.Pos, 0.f);
			Fight.Projectiles.RemoveAtSwap(Index);
		}
	}
}

void ShootBall(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	if (Fight.Tick < Self.BallReadyTick)
	{
		return;
	}
	Self.BallReadyTick = Fight.Tick + JamSim::Ticks(Balance.BallCooldown);
	FJamProjectile Ball;
	Ball.Id = Fight.NextId++;
	Ball.Kind = EJamProjectile::Ball;
	Ball.Owner = Side;
	// The ball starts just outside the body: it is seen leaving the fighter.
	Ball.Pos = Ball.PrevPos = Self.Pos + Self.Facing * (Self.Radius + Balance.BallRadius);
	Ball.Vel = Self.Facing * Balance.BallSpeed;
	Ball.Radius = Balance.BallRadius;
	Ball.Damage = Balance.BallDamage;
	Ball.DieTick = Fight.Tick + JamSim::Ticks(Balance.BallLife);
	Fight.Projectiles.Add(Ball);
	AddEvent(Fight, EJamEvent::ProjectileSpawned, Side, Ball.Id, Ball.Pos, 0.f);
}
} // namespace

FJamFight JamFightRules::Start(const FJamBalanceData& Balance, int32 Seed)
{
	FJamFight Fight;
	Fight.Stream.Initialize(Seed);
	Fight.Fighters[EJamSide::Hero] =
		MakeFighter(Balance.ArenaRadius * HeroStartX, 1.f, Balance.HeroRadius, Balance.HeroSpeed, Balance.HeroHealth);
	Fight.Fighters[EJamSide::Boss] =
		MakeFighter(Balance.ArenaRadius * BossStartX, -1.f, Balance.BossRadius, Balance.BossSpeed, Balance.BossHealth);
	return Fight;
}

void JamFightRules::Step(FJamFight& Fight, const FJamIntents& Intents, const FJamBalanceData& Balance)
{
	Fight.Events.Reset();
	for (const EJamSide Side : { EJamSide::Hero, EJamSide::Boss })
	{
		MoveFighter(Fight, Side, Intents[Side], Balance);
	}
	// Projectiles fly before new ones are shot, so a new one is first seen at the muzzle.
	AdvanceProjectiles(Fight, Balance);
	for (const EJamSide Side : { EJamSide::Hero, EJamSide::Boss })
	{
		if (Intents[Side].bPrimary)
		{
			ShootBall(Fight, Side, Balance);
		}
	}
	++Fight.Tick;
}
#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * The fight as a pure function of its state, two intents and the balance numbers. No actors, no clocks, no globals: the
 * same seed and the same intents give the same fight, which is what the tests and the bot playthrough rely on.
 * Tests: Jam.Move.*, Jam.Aim.FighterFacesTheAim, Jam.Shot.*, Jam.Projectile.IgnoresItsOwner, Jam.Health.BallDamagesTheBoss
 */
namespace JamFightRules
{
/** A fresh fight: the hero and the boss on their marks at full health. */
JAMGAME_API FJamFight Start(const FJamBalanceData& Balance, int32 Seed);

/** One fixed step of JamSim::StepDt seconds. Fight.Events holds what happened in it. */
JAMGAME_API void Step(FJamFight& Fight, const FJamIntents& Intents, const FJamBalanceData& Balance);
} // namespace JamFightRules
#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * Flight of the projectiles: balls now, shurikens and memos later.
 * Tests: Jam.Projectile.*
 */
namespace JamProjectileRules
{
/**
 * True when a round projectile that moved from From to To in one step touched a circle. The whole path counts, so a fast
 * projectile does not jump over a thin target.
 */
JAMGAME_API bool SweepHitsCircle(const FVector2D& From, const FVector2D& To, float Radius, const FVector2D& Center, float CircleRadius);

/** True when the projectile left the arena or lived its time. */
JAMGAME_API bool IsGone(const FJamProjectile& Projectile, int32 Tick, float ArenaRadius);
} // namespace JamProjectileRules
#include "Sim/JamProjectileRules.h"

bool JamProjectileRules::SweepHitsCircle(
	const FVector2D& From, const FVector2D& To, float Radius, const FVector2D& Center, float CircleRadius)
{
	const FVector2D Closest = FMath::ClosestPointOnSegment2D(Center, From, To);
	const double Reach = Radius + CircleRadius;
	return FVector2D::DistSquared(Closest, Center) <= Reach * Reach;
}

bool JamProjectileRules::IsGone(const FJamProjectile& Projectile, int32 Tick, float ArenaRadius)
{
	return Tick >= Projectile.DieTick || Projectile.Pos.SizeSquared() > FMath::Square(static_cast<double>(ArenaRadius));
}
#pragma once

#include "CoreMinimal.h"

/**
 * Health arithmetic of a fighter.
 * Tests: Jam.Health.*
 */
namespace JamHealthRules
{
/** Health after a hit: never below zero, untouched while invulnerable, and damage never heals. */
JAMGAME_API float Apply(float Health, float Damage, bool bInvulnerable);
} // namespace JamHealthRules
#include "Core/JamBalanceRules.h"

#include "UObject/UnrealType.h"

TArray<FString> JamBalanceRules::Problems(const FJamBalanceData& Balance)
{
	TArray<FString> Result;
	// Every number is a size, a speed, a time or an amount: zero means the line is missing.
	for (TFieldIterator<FFloatProperty> It(FJamBalanceData::StaticStruct()); It; ++It)
	{
		if (It->GetPropertyValue_InContainer(&Balance) <= 0.f)
		{
			Result.Add(FString::Printf(TEXT("%s must be positive"), *It->GetName()));
		}
	}
	if (Balance.ArenaRadius <= 2.f * (Balance.HeroRadius + Balance.BossRadius))
	{
		Result.Add(TEXT("ArenaRadius must leave room for both fighters side by side"));
	}
	return Result;
}
#include "Sim/JamFightSubsystem.h"

#include "Core/JamBalanceRules.h"
#include "Core/JamConfig.h"
#include "JamGame.h"
#include "Sim/JamFightRules.h"
#include "Sim/JamStepRules.h"

namespace
{
// A frame longer than this many steps is a hitch: the fight slows down instead of catching up.
constexpr int32 MaxStepsPerFrame = 8;
} // namespace

void UJamFightSubsystem::Initialize(FSubsystemCollectionBase& Collection)
{
	Super::Initialize(Collection);
	Restart();
}

bool UJamFightSubsystem::DoesSupportWorldType(const EWorldType::Type WorldType) const
{
	return WorldType == EWorldType::Game || WorldType == EWorldType::PIE;
}

void UJamFightSubsystem::Restart()
{
	Balance = JamConfig::Load<FJamBalanceData>(JamConfig::BalanceSection);
	for (const FString& Problem : JamBalanceRules::Problems(Balance))
	{
		UE_LOG(LogJamGame, Error, TEXT("Balance: %s"), *Problem);
	}
	Fight = JamFightRules::Start(Balance, static_cast<int32>(FPlatformTime::Cycles()));
	Intents = FJamIntents();
	Accumulated = 0.f;
	Alpha = 1.f;
	FrameEvents.Reset();
}

void UJamFightSubsystem::Advance(float FrameDt)
{
	const JamStepRules::FFrameSteps Frame = JamStepRules::StepsFor(Accumulated, FrameDt, JamSim::StepDt, MaxStepsPerFrame);
	FrameEvents.Reset();
	for (int32 Index = 0; Index < Frame.Steps; ++Index)
	{
		JamFightRules::Step(Fight, Intents, Balance);
		FrameEvents.Append(Fight.Events);
	}
	Accumulated = Frame.Remainder;
	Alpha = Accumulated / JamSim::StepDt;
}
