#include "CoreMinimal.h"
#include "Misc/AutomationTest.h"

#if WITH_DEV_AUTOMATION_TESTS

#include "Sim/JamHealthRules.h"
#include "Sim/JamProjectileRules.h"
#include "Tests/JamTestHelpers.h"

/**
 * T-005 and T-006: the weak ball shot, projectiles and health.
 * A bug here looks in game like "the ball flies through the boss", "holding the button is a machine gun" or "health
 * goes below zero".
 *
 * Run: Automation RunTests Jam.Shot / Jam.Projectile / Jam.Health
 */
namespace
{
int32 CountEvents(const FJamFight& F, EJamEvent Type)
{
	int32 Count = 0;
	for (const FJamEvent& Event : F.Events)
	{
		Count += Event.Type == Type ? 1 : 0;
	}
	return Count;
}
} // namespace

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamShotSpawnTest, "Jam.Shot.BallSpawnsAlongTheAim", JamTest::Flags)

bool FJamShotSpawnTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = JamTest::Balance();
	FJamFight F = JamTest::Fight(B, FVector2D::ZeroVector, FVector2D(-800.0, 0.0));
	FJamIntents Intents;
	Intents[EJamSide::Hero].Aim.Dir = FVector2D(0.0, 1.0);
	Intents[EJamSide::Hero].bPrimary = true;
	JamFightRules::Step(F, Intents, B);
	if (!TestEqual(TEXT("one press, one ball"), F.Projectiles.Num(), 1))
	{
		return false;
	}
	const FJamProjectile& Ball = F.Projectiles[0];
	TestEqual(TEXT("it is a ball"), Ball.Kind, EJamProjectile::Ball);
	TestEqual(TEXT("it belongs to the hero"), Ball.Owner, EJamSide::Hero);
	TestTrue(TEXT("it flies along the aim at the ball speed"), Ball.Vel.Equals(FVector2D(0.0, B.BallSpeed), 1e-2));
	TestTrue(TEXT("it starts outside the hero's body"), Ball.Pos.Y >= B.HeroRadius);
	TestEqual(TEXT("the step reports the spawn"), CountEvents(F, EJamEvent::ProjectileSpawned), 1);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamShotCooldownTest, "Jam.Shot.CooldownBlocksTheSecondShot", JamTest::Flags)

bool FJamShotCooldownTest::RunTest(const FString& Parameters)
{
	FJamBalanceData B = JamTest::Balance();
	B.BallCooldown = 0.5f;
	B.BallLife = 10.f;
	B.ArenaRadius = 100000.f;
	FJamFight F = JamTest::Fight(B, FVector2D::ZeroVector, FVector2D(-800.0, 0.0));
	FJamIntents Intents;
	Intents[EJamSide::Hero].bPrimary = true;
	JamTest::Run(F, Intents, B, 29);
	TestEqual(TEXT("holding the button for less than the cooldown gives one ball"), F.Projectiles.Num(), 1);
	JamTest::Run(F, Intents, B, 2);
	TestEqual(TEXT("the second ball comes after the cooldown"), F.Projectiles.Num(), 2);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamProjectileSweepTest, "Jam.Projectile.HitsACircleOnItsPath", JamTest::Flags)

bool FJamProjectileSweepTest::RunTest(const FString& Parameters)
{
	// The step jumps over the whole target: the path counts, not the end point.
	TestTrue(TEXT("a path through the circle hits"),
		JamProjectileRules::SweepHitsCircle(FVector2D(-500.0, 0.0), FVector2D(500.0, 0.0), 10.f, FVector2D(0.0, 30.0), 50.f));
	TestTrue(TEXT("a graze counts with the projectile's own radius"),
		JamProjectileRules::SweepHitsCircle(FVector2D(-500.0, 59.0), FVector2D(500.0, 59.0), 10.f, FVector2D::ZeroVector, 50.f));
	TestFalse(TEXT("a path beside the circle misses"),
		JamProjectileRules::SweepHitsCircle(FVector2D(-500.0, 61.0), FVector2D(500.0, 61.0), 10.f, FVector2D::ZeroVector, 50.f));
	TestFalse(TEXT("a path that ends before the circle misses"),
		JamProjectileRules::SweepHitsCircle(FVector2D(-500.0, 0.0), FVector2D(-100.0, 0.0), 10.f, FVector2D::ZeroVector, 50.f));
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamProjectileOwnerTest, "Jam.Projectile.IgnoresItsOwner", JamTest::Flags)

bool FJamProjectileOwnerTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = JamTest::Balance();
	FJamFight F = JamTest::Fight(B, FVector2D::ZeroVector, FVector2D(-800.0, 0.0));
	// A hero ball placed inside the hero and flying across him.
	FJamProjectile Ball;
	Ball.Id = F.NextId++;
	Ball.Owner = EJamSide::Hero;
	Ball.Pos = FVector2D(-10.0, 0.0);
	Ball.Vel = FVector2D(600.0, 0.0);
	Ball.Radius = B.BallRadius;
	Ball.Damage = B.BallDamage;
	Ball.DieTick = 600;
	F.Projectiles.Add(Ball);
	JamTest::Run(F, FJamIntents(), B, 5);
	TestEqual(TEXT("the hero is not hurt by his own ball"), F.Fighters[EJamSide::Hero].Health, B.HeroHealth);
	TestEqual(TEXT("and the ball flies on"), F.Projectiles.Num(), 1);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamProjectileEdgeTest, "Jam.Projectile.DiesOutsideTheArenaOrOfAge", JamTest::Flags)

bool FJamProjectileEdgeTest::RunTest(const FString& Parameters)
{
	FJamProjectile Ball;
	Ball.Pos = FVector2D(1001.0, 0.0);
	Ball.DieTick = 100;
	TestTrue(TEXT("outside the arena"), JamProjectileRules::IsGone(Ball, 0, 1000.f));
	Ball.Pos = FVector2D(0.0, 0.0);
	TestFalse(TEXT("inside and young"), JamProjectileRules::IsGone(Ball, 99, 1000.f));
	TestTrue(TEXT("inside and old"), JamProjectileRules::IsGone(Ball, 100, 1000.f));
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamHealthDamageTest, "Jam.Health.DamageReducesHealth", JamTest::Flags)

bool FJamHealthDamageTest::RunTest(const FString& Parameters)
{
	TestEqual(TEXT("damage is subtracted"), JamHealthRules::Apply(100.f, 30.f, false), 70.f);
	TestEqual(TEXT("health never goes below zero"), JamHealthRules::Apply(10.f, 30.f, false), 0.f);
	TestEqual(TEXT("an invulnerable fighter takes nothing"), JamHealthRules::Apply(100.f, 30.f, true), 100.f);
	TestEqual(TEXT("negative damage does not heal"), JamHealthRules::Apply(50.f, -30.f, false), 50.f);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamHealthBallTest, "Jam.Health.BallDamagesTheBoss", JamTest::Flags)

bool FJamHealthBallTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = JamTest::Balance();
	FJamFight F = JamTest::Fight(B, FVector2D::ZeroVector, FVector2D(600.0, 0.0));
	FJamIntents Intents;
	Intents[EJamSide::Hero].Aim.Dir = FVector2D(1.0, 0.0);
	Intents[EJamSide::Hero].bPrimary = true;
	JamFightRules::Step(F, Intents, B);
	Intents[EJamSide::Hero].bPrimary = false;
	int32 Hits = 0;
	for (int32 i = 0; i < JamSim::StepsPerSecond; ++i)
	{
		JamFightRules::Step(F, Intents, B);
		Hits += CountEvents(F, EJamEvent::Hit);
	}
	TestEqual(TEXT("the boss lost the ball damage"), F.Fighters[EJamSide::Boss].Health, B.BossHealth - B.BallDamage);
	TestEqual(TEXT("exactly one hit was reported"), Hits, 1);
	TestEqual(TEXT("the ball is gone"), F.Projectiles.Num(), 0);
	return true;
}

#endif
#include "CoreMinimal.h"
#include "Misc/AutomationTest.h"

#if WITH_DEV_AUTOMATION_TESTS

#include "Sim/JamBotRules.h"
#include "Tests/JamTestHelpers.h"

/**
 * T-016: the bot that plays a fighter through the same intent as a person.
 * A bug here looks in clips and in full-fight tests like "the bot shoots past the boss" or "the bot hugs the boss and
 * never leaves".
 *
 * Run: Automation RunTests Jam.Bot
 */
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamBotAimTest, "Jam.Bot.AimsAtTheOpponent", JamTest::Flags)

bool FJamBotAimTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = JamTest::Balance();
	const FJamFight F = JamTest::Fight(B, FVector2D(-300.0, 0.0), FVector2D(0.0, 400.0));
	const FJamIntent Intent = JamBotRules::Kite(F, EJamSide::Hero, 500.f);
	TestTrue(TEXT("the aim points from the bot at the opponent"), Intent.Aim.Dir.Equals(FVector2D(0.6, 0.8), 1e-3));
	TestTrue(TEXT("the aim point is the opponent"), Intent.Aim.Point.Equals(FVector2D(0.0, 400.0), 1e-3));
	TestTrue(TEXT("it holds the primary button"), Intent.bPrimary);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamBotRangeTest, "Jam.Bot.KeepsItsRange", JamTest::Flags)

bool FJamBotRangeTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = JamTest::Balance();
	const FVector2D ToBoss(1.0, 0.0);
	const FJamFight Far = JamTest::Fight(B, FVector2D(-900.0, 0.0), FVector2D::ZeroVector);
	const FJamFight Near = JamTest::Fight(B, FVector2D(-200.0, 0.0), FVector2D::ZeroVector);
	const FJamIntent FarIntent = JamBotRules::Kite(Far, EJamSide::Hero, 500.f);
	const FJamIntent NearIntent = JamBotRules::Kite(Near, EJamSide::Hero, 500.f);
	TestTrue(TEXT("too far: it closes in"), FVector2D::DotProduct(FarIntent.Move, ToBoss) > 0.1);
	TestTrue(TEXT("too close: it backs off"), FVector2D::DotProduct(NearIntent.Move, ToBoss) < -0.1);
	TestTrue(TEXT("the move is never longer than a full tilt"), FarIntent.Move.Size() <= 1.0 + 1e-4);
	TestTrue(TEXT("it keeps moving sideways, a standing target is a dead one"), FMath::Abs(NearIntent.Move.Y) > 0.1);
	return true;
}

IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamBotFightTest, "Jam.Bot.WearsDownAStandingBoss", JamTest::Flags)

bool FJamBotFightTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = JamTest::Balance();
	const float Range = 500.f;
	FJamFight F = JamTest::Fight(B, FVector2D(-800.0, 0.0), FVector2D::ZeroVector);
	FJamIntents Intents;
	// Ten seconds of the bot against a boss that only stands.
	double FarthestSide = 0.0;
	for (int32 i = 0; i < 600; ++i)
	{
		Intents[EJamSide::Hero] = JamBotRules::Kite(F, EJamSide::Hero, Range);
		JamFightRules::Step(F, Intents, B);
		FarthestSide = FMath::Max(FarthestSide, FMath::Abs(F.Fighters[EJamSide::Hero].Pos.Y));
	}
	const FJamFighter& Hero = F.Fighters[EJamSide::Hero];
	const FJamFighter& Boss = F.Fighters[EJamSide::Boss];
	const double Gap = FVector2D::Distance(Hero.Pos, Boss.Pos);
	TestTrue(TEXT("most balls land: the boss lost a good part of the 20 shots"), Boss.Health <= Boss.MaxHealth - 10.f * B.BallDamage);
	TestTrue(TEXT("the bot settles near its range"), FMath::Abs(Gap - Range) < 0.3 * Range);
	TestTrue(TEXT("the bot went around the boss, it did not stand"), FarthestSide > 0.5 * Range);
	return true;
}

#endif
#include "Sim/JamFightSubsystem.h"

#include "Core/JamBalanceRules.h"
#include "Core/JamConfig.h"
#include "JamGame.h"
#include "Sim/JamFightRules.h"
#include "Sim/JamStepRules.h"

namespace
{
// A frame longer than this many steps is a hitch: the fight slows down instead of catching up.
constexpr int32 MaxStepsPerFrame = 8;
} // namespace

void UJamFightSubsystem::Initialize(FSubsystemCollectionBase& Collection)
{
	Super::Initialize(Collection);
	Restart();
}

bool UJamFightSubsystem::DoesSupportWorldType(const EWorldType::Type WorldType) const
{
	return WorldType == EWorldType::Game || WorldType == EWorldType::PIE;
}

void UJamFightSubsystem::Restart()
{
	Balance = JamConfig::Load<FJamBalanceData>(JamConfig::BalanceSection);
	for (const FString& Problem : JamBalanceRules::Problems(Balance))
	{
		UE_LOG(LogJamGame, Error, TEXT("Balance: %s"), *Problem);
	}
	Fight = JamFightRules::Start(Balance, static_cast<int32>(FPlatformTime::Cycles()));
	Intents = FJamIntents();
	Accumulated = 0.f;
	Alpha = 1.f;
	FrameEvents.Reset();
}

void UJamFightSubsystem::Advance(float FrameDt)
{
	const JamStepRules::FFrameSteps Frame = JamStepRules::StepsFor(Accumulated, FrameDt, JamSim::StepDt, MaxStepsPerFrame);
	FrameEvents.Reset();
	for (int32 Index = 0; Index < Frame.Steps; ++Index)
	{
		JamFightRules::Step(Fight, Intents, Balance);
		FrameEvents.Append(Fight.Events);
	}
	Accumulated = Frame.Remainder;
	Alpha = Accumulated / JamSim::StepDt;
}
#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "Subsystems/WorldSubsystem.h"

#include "JamFightSubsystem.generated.h"

/**
 * Host of the fight simulation in a game world: holds the state and the balance numbers and runs the fixed steps.
 *
 * It does not tick by itself. The game mode calls Advance once per frame after it has written the intents, so the order
 * inside a frame is always input, simulation, view. Everything else only reads from here.
 */
UCLASS()
class JAMGAME_API UJamFightSubsystem : public UWorldSubsystem
{
	GENERATED_BODY()

public:
	virtual void Initialize(FSubsystemCollectionBase& Collection) override;

	/** Starts the fight over with the numbers from the ini. */
	void Restart();

	/** Runs the fixed steps that fit into the frame. */
	void Advance(float FrameDt);

	const FJamFight& GetFight() const { return Fight; }

	const FJamBalanceData& GetBalance() const { return Balance; }

	/** How far the frame is between the last two steps, 0 to 1: the views interpolate with it. */
	float GetAlpha() const { return Alpha; }

	/** Events of every step run by the last Advance. */
	const TArray<FJamEvent>& GetFrameEvents() const { return FrameEvents; }

	/** What the fighters want. Written by the player controller and the boss brain before Advance. */
	FJamIntents Intents;

protected:
	virtual bool DoesSupportWorldType(const EWorldType::Type WorldType) const override;

private:
	FJamBalanceData Balance;
	FJamFight Fight;
	float Accumulated = 0.f;
	float Alpha = 1.f;
	TArray<FJamEvent> FrameEvents;
};
#include "Sim/JamBotRules.h"

namespace
{
// Share of the range over which the bot goes from "hold the distance" to a full run in or out.
constexpr float RangeSoftness = 0.25f;
} // namespace

FJamIntent JamBotRules::Kite(const FJamFight& Fight, EJamSide Side, float Range)
{
	const FJamFighter& Me = Fight.Fighters[Side];
	const FJamFighter& Target = Fight.Fighters[JamSim::Other(Side)];
	const FVector2D To = Target.Pos - Me.Pos;
	const double Distance = To.Size();
	const FVector2D Dir = Distance > UE_KINDA_SMALL_NUMBER ? To / Distance : Me.Facing;
	const FVector2D Sideways(-Dir.Y, Dir.X);
	const double Radial = FMath::Clamp((Distance - Range) / (Range * RangeSoftness), -1.0, 1.0);

	FJamIntent Intent;
	Intent.Move = (Dir * Radial + Sideways).GetSafeNormal();
	Intent.Aim.Dir = Dir;
	Intent.Aim.Point = Target.Pos;
	Intent.bPrimary = true;
	return Intent;
}
