const TCHAR* CameraName(EJamCameraMode Mode)
{
	switch (Mode)
	{
		case EJamCameraMode::TopDown:
			return TEXT("top-down");
		case EJamCameraMode::Shoulder:
			return TEXT("shoulder");
		default:
			return TEXT("first person");
	}
