// Layout of the prototype HUD as fractions of the screen: presentation only, replaced by Kirill's UI in block E.
constexpr float BossBarWidth = 0.5f;
constexpr float BossBarTop = 0.04f;
constexpr float HeroBarWidth = 0.22f;
constexpr float HeroBarBottom = 0.93f;
constexpr float BarHeight = 0.022f;
constexpr float HudMargin = 0.03f;
constexpr float CrosshairSize = 4.f;
constexpr float TextScale = 1.4f;
const FLinearColor BarBackColor(0.f, 0.f, 0.f, 0.6f);
const FLinearColor BossBarColor(0.9f, 0.15f, 0.15f);
const FLinearColor HeroBarColor(0.2f, 0.9f, 1.0f);
} // namespace

void AJamHUD::DrawBar(float X, float Y, float Width, float Height, float Fraction, const FLinearColor& Color)
{
	DrawRect(BarBackColor, X, Y, Width, Height);
	DrawRect(Color, X, Y, Width * FMath::Clamp(Fraction, 0.f, 1.f), Height);
}

void AJamHUD::DrawHUD()
{
	Super::DrawHUD();
	const UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
	if (!Canvas || !Host)
	{
		return;
	}
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	UFont* Font = GEngine->GetMediumFont();
	const FJamFighter& Hero = Host->GetFight().Fighters[EJamSide::Hero];
	const FJamFighter& Boss = Host->GetFight().Fighters[EJamSide::Boss];

	const float BossX = 0.5f * (1.f - BossBarWidth) * W;
	DrawBar(BossX, BossBarTop * H, BossBarWidth * W, BarHeight * H, Boss.Health / FMath::Max(1.f, Boss.MaxHealth), BossBarColor);
	const FString BossText =
		FString::Printf(TEXT("THE PUBLISHER  %d / %d"), FMath::CeilToInt32(Boss.Health), FMath::CeilToInt32(Boss.MaxHealth));
	DrawText(BossText, FLinearColor::White, BossX, (BossBarTop + BarHeight) * H + 4.f, Font, TextScale);

	DrawBar(HudMargin * W, HeroBarBottom * H, HeroBarWidth * W, BarHeight * H, Hero.Health / FMath::Max(1.f, Hero.MaxHealth), HeroBarColor);
	const FString HeroText = FString::Printf(TEXT("RONIN  %d"), FMath::CeilToInt32(Hero.Health));
	DrawText(HeroText, FLinearColor::White, HudMargin * W, HeroBarBottom * H - 28.f, Font, TextScale);

	const FString CameraText = FString::Printf(TEXT("Camera: %s    F1 top-down   F2 shoulder   F3 first person"), *CameraLabel);
	float CameraTextWidth = 0.f;
	float CameraTextHeight = 0.f;
	GetTextSize(CameraText, CameraTextWidth, CameraTextHeight, Font, 1.f);
	DrawText(CameraText, FLinearColor::White, (1.f - HudMargin) * W - CameraTextWidth, HeroBarBottom * H, Font, 1.f);

	if (bCrosshair)
	{
		DrawRect(FLinearColor::White, 0.5f * W - 0.5f * CrosshairSize, 0.5f * H - 0.5f * CrosshairSize, CrosshairSize, CrosshairSize);
	}
}
