#include "Sim/JamShurikenRules.h"

#include "Sim/JamFightOps.h"

bool JamShurikenRules::IsExplosive(int32 ThrowIndex, int32 Every)
{
	return Every >= 1 && ThrowIndex % Every == 0;
}

bool JamShurikenRules::ExplosionHits(const FVector2D& Center, float Radius, const FVector2D& TargetPos, float TargetRadius)
{
	return FVector2D::DistSquared(Center, TargetPos) <= FMath::Square(static_cast<double>(Radius) + TargetRadius);
}

void JamShurikenRules::Throw(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	if (Fight.Tick < Self.Shuriken.ReadyTick)
	{
		return;
	}
	Self.Shuriken.ReadyTick = Fight.Tick + JamSim::Ticks(Balance.ShurikenCooldown);
	++Self.Shuriken.Throws;
	FJamShot Shot;
	Shot.Kind = EJamProjectile::Shuriken;
	Shot.Speed = Balance.ShurikenSpeed;
	Shot.Radius = Balance.ShurikenRadius;
	Shot.Damage = Balance.ShurikenDamage;
	Shot.Life = Balance.ShurikenLife;
	Shot.bExplosive = IsExplosive(Self.Shuriken.Throws, FMath::RoundToInt32(Balance.ShurikenExplosiveEvery));
	JamFightOps::Shoot(Fight, Side, Self.Facing, Shot);
}

void JamShurikenRules::Explode(FJamFight& Fight, const FJamProjectile& Shuriken, const FJamBalanceData& Balance)
{
	JamFightOps::AddEvent(Fight, EJamEvent::Explosion, Shuriken.Owner, Shuriken.Id, Shuriken.Pos, Balance.ShurikenExplosionRadius);
	const EJamSide TargetSide = JamSim::Other(Shuriken.Owner);
	const FJamFighter& Target = Fight.Fighters[TargetSide];
	if (ExplosionHits(Shuriken.Pos, Balance.ShurikenExplosionRadius, Target.Pos, Target.Radius))
	{
		JamFightOps::Hurt(Fight, TargetSide, Balance.ShurikenExplosionDamage, Target.Pos, Shuriken.Id);
	}
}

#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * The shuriken: a fast projectile on a short cooldown. Every few throws of the same fighter one is explosive: it goes
 * off where it hits or where its flight ends and hurts the thrower's enemy in a radius, never the thrower.
 * Tests: Jam.Shuriken.*, Jam.Fight.ExplosiveShurikenDamagesInRadius, Jam.Fight.CounterBelongsToTheThrower
 */
namespace JamShurikenRules
{
/** ThrowIndex counts a fighter's throws from 1. Every < 1 means no explosive throws. */
JAMGAME_API bool IsExplosive(int32 ThrowIndex, int32 Every);

/** True when the blast touches a round target. */
JAMGAME_API bool ExplosionHits(const FVector2D& Center, float Radius, const FVector2D& TargetPos, float TargetRadius);

/** The fighter holds the shuriken button: throws when the cooldown is over. */
JAMGAME_API void Throw(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance);

/** An explosive shuriken goes off where it is. */
JAMGAME_API void Explode(FJamFight& Fight, const FJamProjectile& Shuriken, const FJamBalanceData& Balance);
} // namespace JamShurikenRules

#include "Sim/JamKatanaRules.h"

#include "Sim/JamFightOps.h"

namespace
{
constexpr int32 StrikesInSeries = 3;
} // namespace

bool JamKatanaRules::InArc(const FVector2D& From, const FVector2D& Facing, const FVector2D& TargetPos, float TargetRadius, float Range,
	float HalfArcDeg)
{
	const FVector2D To = TargetPos - From;
	const double Distance = To.Size();
	if (Distance <= TargetRadius)
	{
		// The attacker stands inside the target: there is no direction to miss in.
		return true;
	}
	if (Distance > Range + TargetRadius)
	{
		return false;
	}
	const double Cos = FMath::Clamp(FVector2D::DotProduct(Facing.GetSafeNormal(), To / Distance), -1.0, 1.0);
	const double Angle = FMath::RadiansToDegrees(FMath::Acos(Cos));
	const double EdgeAngle = FMath::RadiansToDegrees(FMath::Asin(TargetRadius / Distance));
	return Angle <= HalfArcDeg + EdgeAngle;
}

int32 JamKatanaRules::NextStrike(const FJamKatanaState& State, int32 Tick)
{
	if (Tick < State.BusyUntilTick)
	{
		return 0;
	}
	const bool bContinues = State.Strike > 0 && State.Strike < StrikesInSeries && Tick <= State.ChainUntilTick;
	return bContinues ? State.Strike + 1 : 1;
}

FJamKatanaState JamKatanaRules::Begin(int32 Strike, int32 Tick, const FJamBalanceData& Balance)
{
	FJamKatanaState State;
	State.Strike = Strike;
	State.HitTick = Tick + JamSim::Ticks(Balance.KatanaWindUp);
	State.BusyUntilTick = State.HitTick + JamSim::Ticks(Balance.KatanaRecovery);
	State.ChainUntilTick = State.BusyUntilTick + JamSim::Ticks(Balance.KatanaChainWindow);
	State.bHitPending = true;
	return State;
}

float JamKatanaRules::Damage(int32 Strike, const FJamBalanceData& Balance)
{
	return Strike >= StrikesInSeries ? Balance.KatanaFinisherDamage : Balance.KatanaDamage;
}

void JamKatanaRules::Press(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	const int32 Strike = NextStrike(Self.Katana, Fight.Tick);
	if (Strike == 0)
	{
		return;
	}
	Self.Katana = Begin(Strike, Fight.Tick, Balance);
	JamFightOps::Shift(Fight, Side, Self.Facing * Balance.KatanaStep, Balance.ArenaRadius);
	JamFightOps::AddEvent(Fight, EJamEvent::Swing, Side, 0, Self.Pos, static_cast<float>(Strike));
}

void JamKatanaRules::Land(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	if (!Self.Katana.bHitPending || Fight.Tick < Self.Katana.HitTick)
	{
		return;
	}
	Self.Katana.bHitPending = false;
	const EJamSide TargetSide = JamSim::Other(Side);
	const FJamFighter& Target = Fight.Fighters[TargetSide];
	if (InArc(Self.Pos, Self.Facing, Target.Pos, Target.Radius, Balance.KatanaRange, Balance.KatanaHalfArc))
	{
		JamFightOps::Hurt(Fight, TargetSide, Damage(Self.Katana.Strike, Balance), Target.Pos);
	}
}

#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * The katana: a series of three strikes in an arc in front of the fighter, the third one strong. A strike lands once,
 * a wind-up after the press; a press that comes too late starts the series over.
 * Tests: Jam.Katana.*, Jam.Fight.KatanaDamagesOncePerStrike
 */
namespace JamKatanaRules
{
/**
 * True when a round target is touched by the arc: within Range of the attacker's centre (the target's radius counts)
 * and within HalfArcDeg of where he faces (a wide target sticks into the arc with its edge).
 */
JAMGAME_API bool InArc(const FVector2D& From, const FVector2D& Facing, const FVector2D& TargetPos, float TargetRadius, float Range,
	float HalfArcDeg);

/** Which strike a press starts on this step: 1 to 3, or 0 while the previous one is still in progress. */
JAMGAME_API int32 NextStrike(const FJamKatanaState& State, int32 Tick);

/** The state of a strike that starts on this step. */
JAMGAME_API FJamKatanaState Begin(int32 Strike, int32 Tick, const FJamBalanceData& Balance);

JAMGAME_API float Damage(int32 Strike, const FJamBalanceData& Balance);

/** The fighter holds the katana button: starts a strike when one can start. */
JAMGAME_API void Press(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance);

/** Lands the strike whose wind-up ends on this step. */
JAMGAME_API void Land(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance);
} // namespace JamKatanaRules

#include "Sim/JamFightOps.h"

#include "Sim/JamDashRules.h"
#include "Sim/JamHealthRules.h"
#include "Sim/JamMoveRules.h"

void JamFightOps::AddEvent(FJamFight& Fight, EJamEvent Type, EJamSide Side, int32 ProjectileId, const FVector2D& Pos, float Amount)
{
	FJamEvent Event;
	Event.Type = Type;
	Event.Side = Side;
	Event.ProjectileId = ProjectileId;
	Event.Pos = Pos;
	Event.Amount = Amount;
	Fight.Events.Add(Event);
}

bool JamFightOps::Hurt(FJamFight& Fight, EJamSide TargetSide, float Amount, const FVector2D& Pos, int32 ProjectileId)
{
	FJamFighter& Target = Fight.Fighters[TargetSide];
	const bool bInvulnerable = JamDashRules::IsInvulnerable(Target.Dash, Fight.Tick);
	Target.Health = JamHealthRules::Apply(Target.Health, Amount, bInvulnerable);
	if (bInvulnerable)
	{
		return false;
	}
	AddEvent(Fight, EJamEvent::Hit, TargetSide, ProjectileId, Pos, Amount);
	if (Target.Health <= 0.f && Fight.Phase == EJamPhase::Fight)
	{
		Fight.Phase = TargetSide == EJamSide::Hero ? EJamPhase::HeroDead : EJamPhase::Won;
	}
	return true;
}

void JamFightOps::Shoot(FJamFight& Fight, EJamSide Owner, const FVector2D& Dir, const FJamShot& Shot)
{
	const FJamFighter& Self = Fight.Fighters[Owner];
	FJamProjectile Projectile;
	Projectile.Id = Fight.NextId++;
	Projectile.Kind = Shot.Kind;
	Projectile.Owner = Owner;
	Projectile.Pos = Projectile.PrevPos = Self.Pos + Dir * (Self.Radius + Shot.Radius);
	Projectile.Vel = Dir * Shot.Speed;
	Projectile.Radius = Shot.Radius;
	Projectile.Damage = Shot.Damage;
	Projectile.DieTick = Fight.Tick + JamSim::Ticks(Shot.Life);
	Projectile.bExplosive = Shot.bExplosive;
	Fight.Projectiles.Add(Projectile);
	AddEvent(Fight, EJamEvent::ProjectileSpawned, Owner, Projectile.Id, Projectile.Pos, 0.f);
}

void JamFightOps::Shift(FJamFight& Fight, EJamSide Side, const FVector2D& Delta, float ArenaRadius)
{
	FJamFighter& Self = Fight.Fighters[Side];
	const FJamFighter& Other = Fight.Fighters[JamSim::Other(Side)];
	const FVector2D Pos = JamMoveRules::PushOut(Self.Pos + Delta, Self.Radius, Other.Pos, Other.Radius);
	Self.Pos = JamMoveRules::ClampToArena(Pos, Self.Radius, ArenaRadius);
}

