void AJamArenaView::Init(float ArenaRadius)
{
	const float Diameter = 2.f * ArenaRadius / JamShapes::UnitSize;
	Floor->SetRelativeScale3D(FVector(Diameter, Diameter, FloorThickness / JamShapes::UnitSize));
	Floor->SetRelativeLocation(FVector(0.0, 0.0, -0.5 * FloorThickness));
	JamShapes::Paint(*Floor, FloorColor);

	for (int32 Index = 0; Index < PostCount; ++Index)
	{
		const float Angle = UE_TWO_PI * Index / PostCount;
		const FVector Location(ArenaRadius * FMath::Cos(Angle), ArenaRadius * FMath::Sin(Angle), 0.5f * PostHeight);
		AddBox(
			Location, FMath::RadiansToDegrees(Angle), FVector(PostWidth, PostWidth, PostHeight), Index % 2 == 0 ? PostColorA : PostColorB);
	}
	// Each line is a chord of the floor circle, so the grid ends at the edge.
	for (float Offset = GridStep * FMath::CeilToFloat(-ArenaRadius / GridStep + 0.5f); Offset < ArenaRadius; Offset += GridStep)
	{
		const float Chord = 2.f * FMath::Sqrt(FMath::Square(ArenaRadius) - FMath::Square(Offset));
		AddBox(FVector(0.0, Offset, 0.5 * GridHeight), 0.f, FVector(Chord, GridWidth, GridHeight), GridColor);
		AddBox(FVector(Offset, 0.0, 0.5 * GridHeight), 90.f, FVector(Chord, GridWidth, GridHeight), GridColor);
	}
}

void AJamArenaView::AddBox(const FVector& Location, float Yaw, const FVector& Size, const FLinearColor& Color)
{
	UStaticMeshComponent* Box = NewObject<UStaticMeshComponent>(this);
	JamShapes::Setup(*Box, JamShapes::Cube());
	Box->SetupAttachment(RootComponent);
	Box->RegisterComponent();
	Box->SetRelativeLocation(Location);
	Box->SetRelativeRotation(FRotator(0.0, Yaw, 0.0));
	Box->SetRelativeScale3D(Size / JamShapes::UnitSize);
	JamShapes::Paint(*Box, Color);
	Boxes.Add(Box);
}
