const FLinearColor BossTrailColor(0.4f, 0.06f, 0.06f);

/** Seconds an event stays on screen; 0 for the events that are not drawn here. */
float LifeOf(EJamEvent Type)
{
	switch (Type)
	{
		case EJamEvent::Swing:
			return SwingLife;
		case EJamEvent::Explosion:
			return ExplosionLife;
		case EJamEvent::Slam:
			return SlamLife;
		case EJamEvent::Dash:
