	Fight.Boss.BusyUntilTick = Circle.HitTick + JamSim::Ticks(Balance.BossRecovery);
}

void StartVolley(FJamFight& Fight, const FJamBalanceData& Balance)
{
	FJamShot Memo;
	Memo.Kind = EJamProjectile::Memo;
	Memo.Speed = Balance.MemoSpeed;
	Memo.Radius = Balance.MemoRadius;
	Memo.Damage = Balance.MemoDamage;
	Memo.Life = Balance.MemoLife;
	const FVector2D Aim = Fight.Fighters[EJamSide::Boss].Facing;
	for (const FVector2D& Dir : JamBossRules::VolleyDirections(Aim, FMath::RoundToInt32(Balance.MemoCount), Balance.MemoSpread))
	{
		JamFightOps::Shoot(Fight, EJamSide::Boss, Dir, Memo);
	}
	Fight.Boss.VolleyReadyTick = Fight.Tick + JamSim::Ticks(Balance.VolleyCooldown);
	Fight.Boss.BusyUntilTick = Fight.Tick + JamSim::Ticks(Balance.BossRecovery);
}
} // namespace

FJamIntent JamBossRules::Decide(const FJamFight& Fight, const FJamBalanceData& Balance)
{
	const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];
	const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
	const FVector2D To = Hero.Pos - Boss.Pos;
	const double Distance = To.Size();

	FJamIntent Intent;
	Intent.Aim.Dir = Distance > UE_KINDA_SMALL_NUMBER ? To / Distance : Boss.Facing;
	Intent.Aim.Point = Hero.Pos;
	if (IsBusy(Fight))
	{
		return Intent;
	}
	// One attack at a time, the slam first: a hero who came close must pay attention.
	if (Distance <= Balance.SlamRange && Fight.Tick >= Fight.Boss.SlamReadyTick)
	{
		Intent.bSlam = true;
	}
	else if (Fight.Tick >= Fight.Boss.VolleyReadyTick)
	{
		Intent.bVolley = true;
	}
	else if (Distance > Boss.Radius + Hero.Radius + 1.0)
	{
		Intent.Move = Intent.Aim.Dir;
	}
	return Intent;
}

bool JamBossRules::IsBusy(const FJamFight& Fight)
{
	return Fight.Tick < Fight.Boss.BusyUntilTick;
}

TArray<FVector2D> JamBossRules::VolleyDirections(const FVector2D& AimDir, int32 Count, float SpreadDeg)
{
	TArray<FVector2D> Directions;
	const FVector2D Dir = AimDir.GetSafeNormal();
	for (int32 Index = 0; Index < Count; ++Index)
	{
		const float Angle = Count > 1 ? SpreadDeg * (static_cast<float>(Index) / (Count - 1) - 0.5f) : 0.f;
		Directions.Add(Dir.GetRotated(Angle));
	}
	return Directions;
}

void JamBossRules::Act(FJamFight& Fight, const FJamIntent& Intent, const FJamBalanceData& Balance)
{
	if (IsBusy(Fight))
	{
		return;
	}
	if (Intent.bSlam && Fight.Tick >= Fight.Boss.SlamReadyTick)
	{
		StartSlam(Fight, Intent.Aim.Point, Balance);
	}
	else if (Intent.bVolley && Fight.Tick >= Fight.Boss.VolleyReadyTick)
	{
		StartVolley(Fight, Balance);
	}
}
#include "Sim/JamKatanaRules.h"

#include "Sim/JamFightOps.h"

namespace
{
constexpr int32 StrikesInSeries = 3;
} // namespace

bool JamKatanaRules::InArc(
	const FVector2D& From, const FVector2D& Facing, const FVector2D& TargetPos, float TargetRadius, float Range, float HalfArcDeg)
{
	const FVector2D To = TargetPos - From;
	const double Distance = To.Size();
	if (Distance <= TargetRadius)
	{
		// The attacker stands inside the target: there is no direction to miss in.
		return true;
	}
	if (Distance > Range + TargetRadius)
	{
		return false;
	}
	const double Cos = FMath::Clamp(FVector2D::DotProduct(Facing.GetSafeNormal(), To / Distance), -1.0, 1.0);
	const double Angle = FMath::RadiansToDegrees(FMath::Acos(Cos));
	const double EdgeAngle = FMath::RadiansToDegrees(FMath::Asin(TargetRadius / Distance));
	return Angle <= HalfArcDeg + EdgeAngle;
}

int32 JamKatanaRules::NextStrike(const FJamKatanaState& State, int32 Tick)
{
	if (Tick < State.BusyUntilTick)
	{
		return 0;
	}
	const bool bContinues = State.Strike > 0 && State.Strike < StrikesInSeries && Tick <= State.ChainUntilTick;
	return bContinues ? State.Strike + 1 : 1;
}

FJamKatanaState JamKatanaRules::Begin(int32 Strike, int32 Tick, const FJamBalanceData& Balance)
{
	FJamKatanaState State;
	State.Strike = Strike;
	State.HitTick = Tick + JamSim::Ticks(Balance.KatanaWindUp);
	State.BusyUntilTick = State.HitTick + JamSim::Ticks(Balance.KatanaRecovery);
	State.ChainUntilTick = State.BusyUntilTick + JamSim::Ticks(Balance.KatanaChainWindow);
	State.bHitPending = true;
	return State;
}

float JamKatanaRules::Damage(int32 Strike, const FJamBalanceData& Balance)
{
	return Strike >= StrikesInSeries ? Balance.KatanaFinisherDamage : Balance.KatanaDamage;
}

void JamKatanaRules::Press(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	const int32 Strike = NextStrike(Self.Katana, Fight.Tick);
	if (Strike == 0)
	{
		return;
	}
	Self.Katana = Begin(Strike, Fight.Tick, Balance);
	JamFightOps::Shift(Fight, Side, Self.Facing * Balance.KatanaStep, Balance.ArenaRadius);
	JamFightOps::AddEvent(Fight, EJamEvent::Swing, Side, 0, Self.Pos, static_cast<float>(Strike));
}

void JamKatanaRules::Land(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	if (!Self.Katana.bHitPending || Fight.Tick < Self.Katana.HitTick)
	{
		return;
	}
	Self.Katana.bHitPending = false;
	const EJamSide TargetSide = JamSim::Other(Side);
	const FJamFighter& Target = Fight.Fighters[TargetSide];
	if (InArc(Self.Pos, Self.Facing, Target.Pos, Target.Radius, Balance.KatanaRange, Balance.KatanaHalfArc))
	{
		JamFightOps::Hurt(Fight, TargetSide, Damage(Self.Katana.Strike, Balance), Target.Pos);
	}
}
#include "Sim/JamShurikenRules.h"

#include "Sim/JamFightOps.h"

bool JamShurikenRules::IsExplosive(int32 ThrowIndex, int32 Every)
{
	return Every >= 1 && ThrowIndex % Every == 0;
}

bool JamShurikenRules::ExplosionHits(const FVector2D& Center, float Radius, const FVector2D& TargetPos, float TargetRadius)
{
	return FVector2D::DistSquared(Center, TargetPos) <= FMath::Square(static_cast<double>(Radius) + TargetRadius);
}

void JamShurikenRules::Throw(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	FJamFighter& Self = Fight.Fighters[Side];
	if (Fight.Tick < Self.Shuriken.ReadyTick)
	{
		return;
	}
	Self.Shuriken.ReadyTick = Fight.Tick + JamSim::Ticks(Balance.ShurikenCooldown);
	++Self.Shuriken.Throws;
	FJamShot Shot;
	Shot.Kind = EJamProjectile::Shuriken;
	Shot.Speed = Balance.ShurikenSpeed;
	Shot.Radius = Balance.ShurikenRadius;
	Shot.Damage = Balance.ShurikenDamage;
	Shot.Life = Balance.ShurikenLife;
	Shot.bExplosive = IsExplosive(Self.Shuriken.Throws, FMath::RoundToInt32(Balance.ShurikenExplosiveEvery));
	JamFightOps::Shoot(Fight, Side, Self.Facing, Shot);
}

void JamShurikenRules::Explode(FJamFight& Fight, const FJamProjectile& Shuriken, const FJamBalanceData& Balance)
{
	JamFightOps::AddEvent(Fight, EJamEvent::Explosion, Shuriken.Owner, Shuriken.Id, Shuriken.Pos, Balance.ShurikenExplosionRadius);
	const EJamSide TargetSide = JamSim::Other(Shuriken.Owner);
	const FJamFighter& Target = Fight.Fighters[TargetSide];
	if (ExplosionHits(Shuriken.Pos, Balance.ShurikenExplosionRadius, Target.Pos, Target.Radius))
	{
		JamFightOps::Hurt(Fight, TargetSide, Balance.ShurikenExplosionDamage, Target.Pos, Shuriken.Id);
	}
}

