"""Adds balance fields in the three places that must agree: the struct, the ini section and the test fixture.

add_balance.py <project root> <fields file>

The fields file has one field per line: Name | game value | test value | optional comment. A line starting with # is a
group comment that goes above the next field in the struct. Existing fields are left alone.
"""
import sys

root, fields_path = sys.argv[1], sys.argv[2]
header_path = root + "/Source/JamGame/Public/Core/JamBalance.h"
ini_path = root + "/Config/DefaultGame.ini"
fixture_path = root + "/Source/JamGame/Private/Tests/JamTestHelpers.h"


def read(path):
    with open(path, encoding="utf-8", newline="") as handle:
        return handle.read()


def write(path, text):
    with open(path, "w", encoding="utf-8", newline="") as handle:
        handle.write(text)


header, ini, fixture = read(header_path), read(ini_path), read(fixture_path)
ini_eol = "\r\n" if "\r\n" in ini else "\n"
struct_lines, ini_lines, fixture_lines = [], [], []
group = None
for raw in read(fields_path).splitlines():
    line = raw.strip()
    if not line:
        continue
    if line.startswith("#"):
        group = line[1:].strip()
        continue
    parts = [part.strip() for part in line.split("|")]
    name, game, test = parts[0], parts[1], parts[2]
    comment = parts[3] if len(parts) > 3 and parts[3] else group
    group = None
    if "float %s =" % name in header:
        continue
    struct_lines.append("")
    if comment:
        struct_lines.append("\t/** %s */" % comment)
    struct_lines += ["\tUPROPERTY()", "\tfloat %s = 0.f;" % name]
    ini_lines.append("%s=%s" % (name, game))
    test_text = test if "." in test else test + "."
    fixture_lines.append("\tB.%s = %sf;" % (name, test_text))

if not ini_lines:
    raise SystemExit("nothing to add")

end = header.rindex("};")
write(header_path, header[:end] + "\n".join(struct_lines).lstrip("\n").join(["\n", "\n"]) + header[end:])

section = ini.index("[JamBalance]")
section_end = ini.index(ini_eol + ini_eol, section)
write(ini_path, ini[:section_end] + ini_eol + ini_eol.join(ini_lines) + ini[section_end:])

marker = "\treturn B;\n"
if fixture.count(marker) != 1:
    raise SystemExit("fixture: expected one 'return B;'")
write(fixture_path, fixture.replace(marker, "\n".join(fixture_lines) + "\n" + marker))
print("added %d field(s)" % len(ini_lines))
