#include "UI/JamHUD.h"

#include "Engine/Canvas.h"
#include "Engine/Engine.h"
#include "Sim/JamFightSubsystem.h"
#include "Sim/JamLoadoutRules.h"

namespace
{
// Layout of the prototype HUD as fractions of the screen: presentation only, replaced by Kirill's UI in block E.
constexpr float BossBarWidth = 0.5f;
constexpr float BossBarTop = 0.04f;
constexpr float HeroBarWidth = 0.22f;
constexpr float HeroBarBottom = 0.93f;
constexpr float BarHeight = 0.022f;
constexpr float HudMargin = 0.03f;
constexpr float CrosshairSize = 4.f;
constexpr float TextScale = 1.4f;
constexpr float HintRowHeight = 20.f;
constexpr float LoadoutRowHeight = 24.f;
constexpr float LoadoutScale = 1.2f;
constexpr float LoadoutNameOffset = 70.f;
constexpr float EndingBandTop = 0.36f;
constexpr float EndingBandHeight = 0.24f;
constexpr float EndingTitleScale = 3.2f;
const FLinearColor BarBackColor(0.f, 0.f, 0.f, 0.6f);
const FLinearColor BossBarColor(0.9f, 0.15f, 0.15f);
const FLinearColor HeroBarColor(0.2f, 0.9f, 1.0f);
const FLinearColor StolenColor(1.0f, 0.35f, 0.3f);
const FLinearColor EndingBandColor(0.f, 0.f, 0.f, 0.75f);
const FLinearColor WinColor(1.0f, 0.3f, 0.85f);

/** A button of the hero, the mechanic that lives on it and the name of the key. */
struct FLoadoutRow
{
	EJamButton Button;
	EJamMechanic Mechanic;
	const TCHAR* Key;
};

const FLoadoutRow LoadoutRows[] = {
	{ EJamButton::Primary, EJamMechanic::Katana, TEXT("LMB") },
	{ EJamButton::Secondary, EJamMechanic::Shuriken, TEXT("RMB") },
	{ EJamButton::Dash, EJamMechanic::Dash, TEXT("SPACE") },
};
} // namespace

void AJamHUD::DrawBar(float X, float Y, float Width, float Height, float Fraction, const FLinearColor& Color)
{
	DrawRect(BarBackColor, X, Y, Width, Height);
	DrawRect(Color, X, Y, Width * FMath::Clamp(Fraction, 0.f, 1.f), Height);
}

void AJamHUD::DrawLoadout(const FJamLedger& Ledger, float X, float Bottom)
{
	UFont* Font = GEngine->GetMediumFont();
	const int32 RowCount = UE_ARRAY_COUNT(LoadoutRows);
	for (int32 Index = 0; Index < RowCount; ++Index)
	{
		const FLoadoutRow& Row = LoadoutRows[Index];
		const float Y = Bottom - (RowCount - Index) * LoadoutRowHeight;
		const TCHAR* Name = JamLoadoutRules::Name(Row.Mechanic);
		if (Ledger.Has(EJamSide::Hero, Row.Mechanic))
		{
			DrawText(Row.Key, HeroBarColor, X, Y, Font, LoadoutScale);
			DrawText(Name, HeroBarColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
			continue;
		}
		// What is left on the button: the weak ball on the attack buttons, nothing on the dash.
		const bool bBall = JamLoadoutRules::ActionFor(Row.Button, EJamSide::Hero, Ledger) == EJamAction::Ball;
		const FString Left = FString::Printf(TEXT("%s    (%s is the Publisher's now)"), bBall ? TEXT("BALL") : TEXT("nothing"), Name);
		DrawText(Row.Key, StolenColor, X, Y, Font, LoadoutScale);
		DrawText(Left, StolenColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
	}
}

void AJamHUD::DrawHint(const FString& Text, int32 Row)
{
	UFont* Font = GEngine->GetMediumFont();
	float Width = 0.f;
	float Height = 0.f;
	GetTextSize(Text, Width, Height, Font, 1.f);
	DrawText(Text, FLinearColor::White, (1.f - HudMargin) * Canvas->ClipX - Width, HeroBarBottom * Canvas->ClipY - Row * HintRowHeight,
		Font, 1.f);
}

void AJamHUD::DrawCentered(const FString& Text, float Y, float Scale, const FLinearColor& Color)
{
	UFont* Font = GEngine->GetMediumFont();
	float Width = 0.f;
	float Height = 0.f;
	GetTextSize(Text, Width, Height, Font, Scale);
	DrawText(Text, Color, 0.5f * (Canvas->ClipX - Width), Y, Font, Scale);
}

void AJamHUD::DrawEnding(EJamPhase Phase)
{
	if (Phase == EJamPhase::Fight)
	{
		return;
	}
	const bool bWon = Phase == EJamPhase::Won;
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	DrawRect(EndingBandColor, 0.f, EndingBandTop * H, W, EndingBandHeight * H);
	DrawCentered(bWon ? TEXT("NEON RONIN: DIRECTOR'S CUT") : TEXT("SHIPPED AS PROOF OF CONCEPT"), (EndingBandTop + 0.06f) * H,
		EndingTitleScale, bWon ? WinColor : FLinearColor::White);
	DrawCentered(
		bWon ? TEXT("The Publisher is out of the building.   R: play again") : TEXT("The Publisher shipped it without you.   R: try again"),
		(EndingBandTop + 0.17f) * H, TextScale, FLinearColor::White);
}

void AJamHUD::DrawHUD()
{
	Super::DrawHUD();
	const UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
	if (!Canvas || !Host)
	{
		return;
	}
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	UFont* Font = GEngine->GetMediumFont();
	const FJamFight& Fight = Host->GetFight();
	const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
	const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];

	const float BossX = 0.5f * (1.f - BossBarWidth) * W;
	DrawBar(BossX, BossBarTop * H, BossBarWidth * W, BarHeight * H, Boss.Health / FMath::Max(1.f, Boss.MaxHealth), BossBarColor);
	const FString BossText =
		FString::Printf(TEXT("THE PUBLISHER  %d / %d"), FMath::CeilToInt32(Boss.Health), FMath::CeilToInt32(Boss.MaxHealth));
	DrawText(BossText, FLinearColor::White, BossX, (BossBarTop + BarHeight) * H + 4.f, Font, TextScale);

	DrawBar(HudMargin * W, HeroBarBottom * H, HeroBarWidth * W, BarHeight * H, Hero.Health / FMath::Max(1.f, Hero.MaxHealth), HeroBarColor);
	const FString HeroText = FString::Printf(TEXT("RONIN  %d"), FMath::CeilToInt32(Hero.Health));
	const float HeroTextY = HeroBarBottom * H - 28.f;
	DrawText(HeroText, FLinearColor::White, HudMargin * W, HeroTextY, Font, TextScale);
	DrawLoadout(Fight.Ledger, HudMargin * W, HeroTextY - 6.f);

	DrawHint(FString::Printf(TEXT("Camera: %s    F1 top-down   F2 shoulder   F3 first person"), *CameraLabel), 0);
	DrawHint(TEXT("Debug: F5 the Publisher steals   R restart"), 1);

	if (bCrosshair)
	{
		DrawRect(FLinearColor::White, 0.5f * W - 0.5f * CrosshairSize, 0.5f * H - 0.5f * CrosshairSize, CrosshairSize, CrosshairSize);
	}
	DrawEnding(Fight.Phase);
}

#include "Game/JamDemo.h"

#include "Game/JamPlayerController.h"
#include "Misc/App.h"
#include "Misc/CommandLine.h"
#include "Misc/Parse.h"
#include "Sim/JamBotRules.h"
#include "Sim/JamFightSubsystem.h"
#include "UnrealClient.h"
#include "View/JamCameraRig.h"

namespace
{
// Time on each camera before the demo moves to the next one.
constexpr float DemoCameraSeconds = 8.f;
constexpr double CaptureFps = 30.0;
// The Publisher takes a mechanic at these moments, one per camera of the second round, so a clip shows the hero both
// whole and stripped.
const float DemoStealTimes[] = { 24.f, 32.f, 40.f };
// How long the ending title stays before the fight starts over.
constexpr float DemoEndingSeconds = 2.5f;

EJamCameraMode DemoCamera(float Time)
{
	const EJamCameraMode Modes[] = { EJamCameraMode::TopDown, EJamCameraMode::Shoulder, EJamCameraMode::FirstPerson };
	return Modes[FMath::FloorToInt32(Time / DemoCameraSeconds) % UE_ARRAY_COUNT(Modes)];
}
} // namespace

void FJamDemo::Init()
{
	const TCHAR* CommandLine = FCommandLine::Get();
	bOn = FParse::Param(CommandLine, TEXT("JamDemo"));
	FParse::Value(CommandLine, TEXT("JamDemoSeconds="), QuitAfter);
	if (FParse::Value(CommandLine, TEXT("JamCapture="), CaptureDir))
	{
		// A fixed step makes the saved frames an even 30 per second however long a frame takes to save.
		FApp::SetFixedDeltaTime(1.0 / CaptureFps);
		FApp::SetUseFixedTimeStep(true);
	}
}

void FJamDemo::Direct(UJamFightSubsystem& Host, float Time)
{
	const int32 Planned = UE_ARRAY_COUNT(DemoStealTimes);
	if (Steals < Planned && Time >= DemoStealTimes[Steals])
	{
		Host.DebugSteal();
		++Steals;
	}
	if (Host.GetFight().Phase == EJamPhase::Fight)
	{
		EndedAt = -1.f;
	}
	else if (EndedAt < 0.f)
	{
		EndedAt = Time;
	}
	else if (Time - EndedAt >= DemoEndingSeconds)
	{
		Host.Restart();
		EndedAt = -1.f;
	}
}

FJamIntent FJamDemo::Drive(UJamFightSubsystem& Host, AJamPlayerController& Player, AJamCameraRig& Rig, float Time)
{
	Direct(Host, Time);
	const FJamFight& Fight = Host.GetFight();
	const FJamIntent Intent = JamBotRules::Play(Fight, EJamSide::Hero, Host.GetBalance());
	const EJamCameraMode Mode = DemoCamera(Time);
	if (Rig.GetMode() != Mode)
	{
		Player.UseCamera(Rig, Mode, Fight.Fighters[EJamSide::Hero]);
	}
	if (Mode != EJamCameraMode::TopDown)
	{
		Rig.SetLook(FMath::RadiansToDegrees(FMath::Atan2(Intent.Aim.Dir.Y, Intent.Aim.Dir.X)));
	}
	return Intent;
}

void FJamDemo::EndFrame(float Time)
{
	if (!CaptureDir.IsEmpty())
	{
		FScreenshotRequest::RequestScreenshot(CaptureDir / FString::Printf(TEXT("f_%05d.png"), Frame++), true, false);
	}
	if (QuitAfter > 0.f && Time >= QuitAfter)
	{
		RequestEngineExit(TEXT("The demo run is over"));
	}
}

#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"

class AJamCameraRig;
class AJamPlayerController;
class UJamFightSubsystem;

/**
 * The demo run: the bot plays the hero and the camera goes through its three modes. It exists so that a clip can be
 * recorded and the game looked at with nobody at the PC. Switched on from the command line:
 *
 *   -JamDemo               the bot plays, the camera changes every few seconds
 *   -JamCapture=<folder>   every frame is saved there as a PNG, at a fixed 30 frames per second
 *   -JamDemoSeconds=<n>    the game quits after n seconds
 */
struct FJamDemo
{
	/** Reads the command line. */
	void Init();

	bool IsOn() const { return bOn; }

	/**
	 * The hero's intent of the frame. Also directs the show: switches the camera, turns the look after the bot's aim,
	 * lets the Publisher take a mechanic at the planned moments and starts a finished fight over.
	 */
	FJamIntent Drive(UJamFightSubsystem& Host, AJamPlayerController& Player, AJamCameraRig& Rig, float Time);

	/** Saves the frame if asked to and quits when the time is up. */
	void EndFrame(float Time);

private:
	void Direct(UJamFightSubsystem& Host, float Time);

	bool bOn = false;
	FString CaptureDir;
	float QuitAfter = 0.f;
	int32 Frame = 0;
	/** Planned steals already made. */
	int32 Steals = 0;
	/** When the fight on screen ended; negative while it goes on. */
	float EndedAt = -1.f;
};

