2	
3	#include "Sim/JamBossRules.h"
4	#include "Sim/JamDashRules.h"
5	#include "Sim/JamFightOps.h"
6	#include "Sim/JamHazardRules.h"
7	#include "Sim/JamKatanaRules.h"
8	#include "Sim/JamLoadoutRules.h"
9	#include "Sim/JamMoveRules.h"
10	#include "Sim/JamProjectileRules.h"
11	#include "Sim/JamShurikenRules.h"
12	
13	namespace
14	{
15	// Where the fighters start, as fractions of the arena radius along X: the hero looks at the boss across the centre.
16	constexpr float HeroStartX = -0.5f;
17	constexpr float BossStartX = 0.3f;
18	
19	FJamFighter MakeFighter(float X, float FacingX, float Radius, float Speed, float Health)
20	{
21		FJamFighter Fighter;
22		Fighter.Pos = Fighter.PrevPos = FVector2D(X, 0.0);
23		Fighter.Facing = FVector2D(FacingX, 0.0);
24		Fighter.Radius = Radius;
25		Fighter.Speed = Speed;
26		Fighter.Health = Fighter.MaxHealth = Health;
27		return Fighter;
28	}
29	
30	/** The boss stands through his attacks and the pause after them, whatever his intent says. */
31	bool IsHeld(const FJamFight& Fight, EJamSide Side)
32	{
33		return Side == EJamSide::Boss && JamBossRules::IsBusy(Fight);
34	}
35	
36	void MoveFighter(FJamFight& Fight, EJamSide Side, const FJamIntent& Intent, const FJamBalanceData& Balance)
37	{
38		FJamFighter& Self = Fight.Fighters[Side];
39		Self.PrevPos = Self.Pos;
40		if (!Intent.Aim.Dir.IsNearlyZero())
41		{
42			Self.Facing = Intent.Aim.Dir.GetSafeNormal();
43		}
44		const bool bHeld = IsHeld(Fight, Side);
45		const bool bOwnsDash = JamLoadoutRules::ActionFor(EJamButton::Dash, Side, Fight.Ledger) == EJamAction::Dash;
46		if (Intent.bDash && bOwnsDash && !bHeld && JamDashRules::CanStart(Self.Dash, Fight.Tick))
47		{
48			Self.Dash = JamDashRules::Start(JamDashRules::Direction(Intent.Move, Self.Facing), Fight.Tick, Balance);
49			JamFightOps::AddEvent(Fight, EJamEvent::Dash, Side, 0, Self.Pos, 0.f);
50		}
51		FVector2D Delta = FVector2D::ZeroVector;
52		if (JamDashRules::IsDashing(Self.Dash, Fight.Tick))
53		{
54			// A dash keeps its line: the stick is not read until it ends.
55			Delta = Self.Dash.Dir * Self.Dash.StepLength;
56		}
57		else if (!bHeld)
58		{
59			Delta = JamMoveRules::Velocity(Intent.Move, Self.Speed) * JamSim::StepDt;
60		}
61		// A fighter that stands is never nudged, whoever walks into it.
62		if (!Delta.IsNearlyZero())
63		{
64			JamFightOps::Shift(Fight, Side, Delta, Balance.ArenaRadius);
65		}
