7	void StartSlam(FJamFight& Fight, const FVector2D& Point, const FJamBalanceData& Balance)
8	{
9		const int32 Telegraph = JamSim::Ticks(Balance.SlamTelegraph);
10		FJamHazard Circle;
11		Circle.Id = Fight.NextId++;
12		Circle.Owner = EJamSide::Boss;
13		Circle.Pos = Point;
14		Circle.Radius = Balance.SlamRadius;
15		Circle.Damage = Balance.SlamDamage;
16		Circle.StartTick = Fight.Tick;
17		Circle.HitTick = Fight.Tick + Telegraph;
18		Fight.Hazards.Add(Circle);
19		Fight.Boss.SlamReadyTick = Fight.Tick + JamSim::Ticks(Balance.SlamCooldown);
20		Fight.Boss.BusyUntilTick = Circle.HitTick + JamSim::Ticks(Balance.BossRecovery);
21	}
