23	void StartVolley(FJamFight& Fight, const FJamBalanceData& Balance)
24	{
25		FJamShot Memo;
26		Memo.Kind = EJamProjectile::Memo;
27		Memo.Speed = Balance.MemoSpeed;
28		Memo.Radius = Balance.MemoRadius;
29		Memo.Damage = Balance.MemoDamage;
30		Memo.Life = Balance.MemoLife;
31		const FVector2D Aim = Fight.Fighters[EJamSide::Boss].Facing;
32		for (const FVector2D& Dir : JamBossRules::VolleyDirections(Aim, FMath::RoundToInt32(Balance.MemoCount), Balance.MemoSpread))
33		{
34			JamFightOps::Shoot(Fight, EJamSide::Boss, Dir, Memo);
35		}
36		Fight.Boss.VolleyReadyTick = Fight.Tick + JamSim::Ticks(Balance.VolleyCooldown);
37		Fight.Boss.BusyUntilTick = Fight.Tick + JamSim::Ticks(Balance.BossRecovery);
38	}
39	} // namespace
40	
41	FJamIntent JamBossRules::Decide(const FJamFight& Fight, const FJamBalanceData& Balance)
42	{
43		const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];
44		const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
45		const FVector2D To = Hero.Pos - Boss.Pos;
46		const double Distance = To.Size();
