#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/** What a projectile is made of when it is shot. */
struct FJamShot
{
	EJamProjectile Kind = EJamProjectile::Ball;
	float Speed = 0.f;
	float Radius = 0.f;
	float Damage = 0.f;
	/** Seconds of flight. */
	float Life = 0.f;
	bool bExplosive = false;
};

/**
 * The few things every mechanic does to the fight: report an event, hurt a fighter, shoot a projectile, shove a body.
 * They are shared so that the hero's katana and the boss's slam take health by the same rule.
 * Tests: Jam.Fight.*, Jam.Shot.*, Jam.Health.BallDamagesTheBoss
 */
namespace JamFightOps
{
JAMGAME_API void AddEvent(FJamFight& Fight, EJamEvent Type, EJamSide Side, int32 ProjectileId, const FVector2D& Pos, float Amount);

/**
 * Takes health from a fighter and reports the hit; at zero health the fight is over. A fighter inside his dash window
 * takes nothing: then the result is false.
 */
JAMGAME_API bool Hurt(FJamFight& Fight, EJamSide TargetSide, float Amount, const FVector2D& Pos, int32 ProjectileId = 0);

/** A projectile leaves the fighter along Dir. It starts just outside his body, so it is seen leaving him. */
JAMGAME_API void Shoot(FJamFight& Fight, EJamSide Owner, const FVector2D& Dir, const FJamShot& Shot);

/** Moves a fighter by Delta, around the other fighter and inside the arena. */
JAMGAME_API void Shift(FJamFight& Fight, EJamSide Side, const FVector2D& Delta, float ArenaRadius);
} // namespace JamFightOps

#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * The Publisher: his brain and his own two attacks. The brain writes the same intent a player writes; it chases the
 * hero, slams when he is close, throws a fan of memos when he is not, and stands still for a moment after each attack:
 * that pause is the player's opening.
 * Tests: Jam.Boss.*
 */
namespace JamBossRules
{
/** What the boss wants to do on this step. */
JAMGAME_API FJamIntent Decide(const FJamFight& Fight, const FJamBalanceData& Balance);

/** True while the boss stands: an attack in progress or the pause after it. */
JAMGAME_API bool IsBusy(const FJamFight& Fight);

/** Directions of a volley: an even fan of Count unit vectors, SpreadDeg wide, around the aim. */
JAMGAME_API TArray<FVector2D> VolleyDirections(const FVector2D& AimDir, int32 Count, float SpreadDeg);

/** Starts the attack the intent asks for, when the boss is free and the attack is ready. */
JAMGAME_API void Act(FJamFight& Fight, const FJamIntent& Intent, const FJamBalanceData& Balance);
} // namespace JamBossRules

#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/** The buttons of a fighter that a mechanic can sit on. */
enum class EJamButton : uint8
{
	Primary,
	Secondary,
	Dash
};

/** What a button does this very moment. */
enum class EJamAction : uint8
{
	None,
	Ball,
	Katana,
	Shuriken,
	Dash
};

/**
 * Who can do what. Every mechanic has one owner; the hero's attack buttons fall back to the weak ball when their
 * mechanic is gone, the boss gets nothing he was not given.
 * Tests: Jam.Loadout.*
 */
namespace JamLoadoutRules
{
/** The action behind a button for a side with this ledger. */
JAMGAME_API EJamAction ActionFor(EJamButton Button, EJamSide Side, const FJamLedger& Ledger);

/** Moves one mechanic to a new owner. */
JAMGAME_API void Give(FJamLedger& Ledger, EJamMechanic Mechanic, EJamSide NewOwner);

/** The first mechanic the side owns, in the order of the enum. False when it owns none. */
JAMGAME_API bool FirstOwned(const FJamLedger& Ledger, EJamSide Side, EJamMechanic& OutMechanic);

/** Name of a mechanic for the screen. */
JAMGAME_API const TCHAR* Name(EJamMechanic Mechanic);
} // namespace JamLoadoutRules

