3	EJamAction JamLoadoutRules::ActionFor(EJamButton Button, EJamSide Side, const FJamLedger& Ledger)
4	{
5		// Only the hero has the ball: it is what is left of him when a mechanic is gone.
6		const EJamAction Fallback = Side == EJamSide::Hero ? EJamAction::Ball : EJamAction::None;
7		switch (Button)
8		{
9			case EJamButton::Primary:
10				return Ledger.Has(Side, EJamMechanic::Katana) ? EJamAction::Katana : Fallback;
11			case EJamButton::Secondary:
12				return Ledger.Has(Side, EJamMechanic::Shuriken) ? EJamAction::Shuriken : Fallback;
13			default:
14				return Ledger.Has(Side, EJamMechanic::Dash) ? EJamAction::Dash : EJamAction::None;
15		}
16	}
17	
18	void JamLoadoutRules::Give(FJamLedger& Ledger, EJamMechanic Mechanic, EJamSide NewOwner)
19	{
20		Ledger.Owner[static_cast<int32>(Mechanic)] = NewOwner;
21	}
