23	bool JamLoadoutRules::FirstOwned(const FJamLedger& Ledger, EJamSide Side, EJamMechanic& OutMechanic)
24	{
25		for (int32 Index = 0; Index < JamSim::MechanicCount; ++Index)
26		{
27			if (Ledger.Owner[Index] == Side)
28			{
29				OutMechanic = static_cast<EJamMechanic>(Index);
30				return true;
31			}
32		}
33		return false;
34	}
