	TestEqual(TEXT("after the third nothing holds the health"), JamStealRules::ThresholdHealth(3, B), 0.f);
	TestEqual(TEXT("health above the floor is left alone"), JamStealRules::ClampToThreshold(800.f, 750.f), 800.f);
