6	
7	void JamFightOps::AddEvent(FJamFight& Fight, EJamEvent Type, EJamSide Side, int32 ProjectileId, const FVector2D& Pos, float Amount)
8	{
9		FJamEvent Event;
10		Event.Type = Type;
11		Event.Side = Side;
12		Event.ProjectileId = ProjectileId;
13		Event.Pos = Pos;
14		Event.Amount = Amount;
15		Fight.Events.Add(Event);
16	}
17	
18	bool JamFightOps::Hurt(FJamFight& Fight, EJamSide TargetSide, float Amount, const FVector2D& Pos, int32 ProjectileId)
19	{
20		FJamFighter& Target = Fight.Fighters[TargetSide];
21		const bool bInvulnerable = JamDashRules::IsInvulnerable(Target.Dash, Fight.Tick);
22		Target.Health = JamHealthRules::Apply(Target.Health, Amount, bInvulnerable);
23		if (bInvulnerable)
24		{
25			return false;
26		}
27		AddEvent(Fight, EJamEvent::Hit, TargetSide, ProjectileId, Pos, Amount);
28		if (Target.Health <= 0.f && Fight.Phase == EJamPhase::Fight)
29		{
30			Fight.Phase = TargetSide == EJamSide::Hero ? EJamPhase::HeroDead : EJamPhase::Won;
31		}
32		return true;
33	}
34	
35	void JamFightOps::Shoot(FJamFight& Fight, EJamSide Owner, const FVector2D& Dir, const FJamShot& Shot)
36	{
37		const FJamFighter& Self = Fight.Fighters[Owner];
38		FJamProjectile Projectile;
39		Projectile.Id = Fight.NextId++;
