10	bool JamKatanaRules::InArc(
11		const FVector2D& From, const FVector2D& Facing, const FVector2D& TargetPos, float TargetRadius, float Range, float HalfArcDeg)
12	{
13		const FVector2D To = TargetPos - From;
14		const double Distance = To.Size();
15		if (Distance <= TargetRadius)
16		{
17			// The attacker stands inside the target: there is no direction to miss in.
18			return true;
19		}
20		if (Distance > Range + TargetRadius)
21		{
22			return false;
23		}
24		const double Cos = FMath::Clamp(FVector2D::DotProduct(Facing.GetSafeNormal(), To / Distance), -1.0, 1.0);
25		const double Angle = FMath::RadiansToDegrees(FMath::Acos(Cos));
26		const double EdgeAngle = FMath::RadiansToDegrees(FMath::Asin(TargetRadius / Distance));
27		return Angle <= HalfArcDeg + EdgeAngle;
28	}
