1	#include "Sim/JamBotRules.h"
2	
3	#include "Sim/JamBossRules.h"
4	
5	namespace
6	{
7	// Share of the range over which the bot goes from "hold the distance" to a full run in or out.
8	constexpr float RangeSoftness = 0.25f;
9	// The bot holds its distance at this share of the slam range: too far to be slammed, close enough to run in.
10	constexpr float RangeOverSlam = 1.5f;
11	// How far outside a warning circle the bot wants to be before it stops running.
12	constexpr float CircleMargin = 30.f;
13	// A projectile that arrives sooner than this is dodged with the dash.
14	constexpr float DodgeSeconds = 0.15f;
15	constexpr float DodgeMargin = 10.f;
16	
17	/** The enemy's warning circle the fighter stands in, if there is one. */
18	const FJamHazard* CircleOver(const FJamFight& Fight, EJamSide Side)
19	{
20		const FVector2D Pos = Fight.Fighters[Side].Pos;
21		for (const FJamHazard& Hazard : Fight.Hazards)
22		{
23			if (Hazard.Owner != Side && FVector2D::Distance(Hazard.Pos, Pos) < Hazard.Radius + CircleMargin)
24			{
25				return &Hazard;
26			}
27		}
28		return nullptr;
29	}
30	
31	/** True when an enemy projectile reaches the fighter within the dodge time if he stays where he is. */
32	bool IsAboutToBeHit(const FJamFight& Fight, EJamSide Side)
33	{
34		const FJamFighter& Me = Fight.Fighters[Side];
35		for (const FJamProjectile& Flying : Fight.Projectiles)
36		{
37			if (Flying.Owner == Side)
38			{
39				continue;
40			}
41			const FVector2D Closest = FMath::ClosestPointOnSegment2D(Me.Pos, Flying.Pos, Flying.Pos + Flying.Vel * DodgeSeconds);
42			if (FVector2D::Distance(Closest, Me.Pos) < Me.Radius + Flying.Radius + DodgeMargin)
43			{
44				return true;
45			}
46		}
47		return false;
48	}
49	} // namespace
50	
51	FJamIntent JamBotRules::Kite(const FJamFight& Fight, EJamSide Side, float Range)
52	{
53		const FJamFighter& Me = Fight.Fighters[Side];
54		const FJamFighter& Target = Fight.Fighters[JamSim::Other(Side)];
55		const FVector2D To = Target.Pos - Me.Pos;
56		const double Distance = To.Size();
57		const FVector2D Dir = Distance > UE_KINDA_SMALL_NUMBER ? To / Distance : Me.Facing;
58		const FVector2D Sideways(-Dir.Y, Dir.X);
59		const double Radial = FMath::Clamp((Distance - Range) / (Range * RangeSoftness), -1.0, 1.0);
60	
61		FJamIntent Intent;
62		Intent.Move = (Dir * Radial + Sideways).GetSafeNormal();
63		Intent.Aim.Dir = Dir;
64		Intent.Aim.Point = Target.Pos;
65		Intent.bPrimary = true;
66		return Intent;
67	}
68	
69	FJamIntent JamBotRules::Play(const FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
70	{
71		const FJamFighter& Me = Fight.Fighters[Side];
72		const FJamFighter& Target = Fight.Fighters[JamSim::Other(Side)];
73		const bool bHasKatana = Fight.Ledger.Has(Side, EJamMechanic::Katana);
74		const bool bInReach = FVector2D::Distance(Me.Pos, Target.Pos) <= Balance.KatanaRange + Target.Radius;
75	
76		FJamIntent Intent = Kite(Fight, Side, Balance.SlamRange * RangeOverSlam);
77		// The katana is not swung at the air; the ball on the same button is shot from anywhere.
78		Intent.bPrimary = !bHasKatana || bInReach;
79		Intent.bSecondary = true;
80		Intent.bDash = IsAboutToBeHit(Fight, Side);
81		if (const FJamHazard* Circle = CircleOver(Fight, Side))
82		{
83			// Out of the circle first, by the shortest way; from its very centre any way is as good, so away from the enemy.
84			const FVector2D Away = Me.Pos - Circle->Pos;
85			Intent.Move = Away.IsNearlyZero() ? -Intent.Aim.Dir : Away.GetSafeNormal();
86			Intent.bDash = true;
87		}
88		else if (bHasKatana && Side == EJamSide::Hero && JamBossRules::IsBusy(Fight))
89		{
90			// The boss stands after his attack: this is when the katana pays.
91			Intent.Move = Intent.Aim.Dir;
92		}
93		return Intent;
94	}
95

