bool FJamStolenNothingTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = JamTest::Balance();
	FJamFight F = JamTest::Fight(B, FVector2D(-240.0, 0.0), FVector2D::ZeroVector);
