	FJamIntents Pushy;
	Pushy[EJamSide::Boss].Aim.Dir = FVector2D(-1.0, 0.0);
	Pushy[EJamSide::Boss].bPrimary = true;
	Pushy[EJamSide::Boss].bSecondary = true;
	Pushy[EJamSide::Boss].bDash = true;
