class AJamCameraRig;
class AJamPlayerController;
class UJamFightSubsystem;

/**
 * The demo run: the bot plays the hero and the camera goes through its three modes. It exists so that a clip can be
 * recorded and the game looked at with nobody at the PC. Switched on from the command line:
 *
 *   -JamDemo               the bot plays, the camera changes every few seconds
 *   -JamCapture=<folder>   every frame is saved there as a PNG, at a fixed 30 frames per second
 *   -JamDemoSeconds=<n>    the game quits after n seconds
 */
struct FJamDemo
{
	/** Reads the command line. */
	void Init();

	bool IsOn() const { return bOn; }

	/**
	 * The hero's intent of the frame. Also directs the show: switches the camera, turns the look after the bot's aim,
	 * lets the Publisher take a mechanic at the planned moments and starts a finished fight over.
	 */
	FJamIntent Drive(UJamFightSubsystem& Host, AJamPlayerController& Player, AJamCameraRig& Rig, float Time);

	/** Saves the frame if asked to and quits when the time is up. */
	void EndFrame(float Time);

private:
	void Direct(UJamFightSubsystem& Host, float Time);

	bool bOn = false;
	FString CaptureDir;
	float QuitAfter = 0.f;
	int32 Frame = 0;
	/** Planned steals already made. */
	int32 Steals = 0;
	/** When the fight on screen ended; negative while it goes on. */
	float EndedAt = -1.f;
};

