7	namespace
8	{
9	// Greybox look of the effects: presentation only. Lives are in seconds, sizes in cm.
10	constexpr float SwingLife = 0.16f;
11	constexpr float ExplosionLife = 0.2f;
12	constexpr float SlamLife = 0.25f;
13	constexpr float TrailLife = 0.22f;
14	constexpr float BladeHeight = 110.f;
15	constexpr float BladeWidth = 16.f;
16	constexpr float BladeThickness = 6.f;
17	constexpr float FinisherScale = 1.25f;
18	constexpr float GroundThickness = 2.f;
19	// Flat shapes lie in layers a little above the floor so they do not flicker through each other.
20	constexpr float CircleHeight = 3.f;
21	constexpr float FillHeight = 5.f;
22	constexpr float FlashHeight = 7.f;
23	constexpr float TrailHeight = 4.f;
24	constexpr float ExplosionStartSize = 0.4f;
25	const FLinearColor CircleColor(0.22f, 0.02f, 0.03f);
26	const FLinearColor FillColor(1.0f, 0.12f, 0.1f);
27	const FLinearColor SlamColor(1.0f, 0.85f, 0.7f);
28	const FLinearColor ExplosionColor(1.0f, 0.55f, 0.08f);
29	const FLinearColor HeroBladeColor(0.75f, 1.0f, 1.0f);
30	const FLinearColor BossBladeColor(1.0f, 0.45f, 0.3f);
31	const FLinearColor FinisherColor(1.0f, 0.3f, 0.85f);
32	const FLinearColor HeroTrailColor(0.05f, 0.35f, 0.5f);
33	const FLinearColor BossTrailColor(0.4f, 0.06f, 0.06f);
34	
35	/** Seconds an event stays on screen; 0 for the events that are not drawn here. */
36	float LifeOf(EJamEvent Type)
37	{
38		switch (Type)
39		{
40			case EJamEvent::Swing:
41				return SwingLife;
42			case EJamEvent::Explosion:
43				return ExplosionLife;
44			case EJamEvent::Slam:
45				return SlamLife;
46			case EJamEvent::Dash:
47				return TrailLife;
48			default:
