54	AJamEffectsView::AJamEffectsView()
55	{
56		PrimaryActorTick.bCanEverTick = false;
57		SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
58		// The pool is filled at runtime: the shapes have to be found here, in a constructor.
59		JamShapes::Cylinder();
60		JamShapes::Cube();
61		JamShapes::Material();
62	}
63	
64	void AJamEffectsView::Init(const FJamBalanceData& Balance)
65	{
66		KatanaRange = Balance.KatanaRange;
67		KatanaHalfArc = Balance.KatanaHalfArc;
68	}
69	
70	UStaticMeshComponent& AJamEffectsView::Take(UStaticMesh* Mesh, const FLinearColor& Color)
71	{
72		if (Used == Pool.Num())
73		{
74			UStaticMeshComponent* Shape = NewObject<UStaticMeshComponent>(this);
75			JamShapes::Setup(*Shape, Mesh);
76			Shape->SetupAttachment(RootComponent);
77			Shape->RegisterComponent();
78			Pool.Add(Shape);
79		}
80		UStaticMeshComponent& Shape = *Pool[Used++];
81		if (Shape.GetStaticMesh() != Mesh)
82		{
83			Shape.SetStaticMesh(Mesh);
84		}
85		Shape.SetVisibility(true);
86		JamShapes::Paint(Shape, Color);
87		return Shape;
88	}
89	
90	void AJamEffectsView::DrawDisc(const FVector2D& Pos, float Radius, float Height, const FLinearColor& Color)
91	{
92		UStaticMeshComponent& Disc = Take(JamShapes::Cylinder(), Color);
93		Disc.SetWorldLocationAndRotation(FVector(Pos.X, Pos.Y, Height), FRotator::ZeroRotator);
94		Disc.SetWorldScale3D(FVector(2.f * Radius, 2.f * Radius, GroundThickness) / JamShapes::UnitSize);
95	}
96	
97	void AJamEffectsView::DrawCircles(const FJamFight& Fight, float Alpha)
98	{
99		// Fight.Tick is the step to come: the picture is between the two before it.
100		const float Tick = Fight.Tick - 1.f + Alpha;
101		for (const FJamHazard& Hazard : Fight.Hazards)
102		{
103			DrawDisc(Hazard.Pos, Hazard.Radius, CircleHeight, CircleColor);
104			// The fill grows to the edge of the circle exactly when it hits: the player reads the time left from it.
105			DrawDisc(Hazard.Pos, Hazard.Radius * JamHazardRules::Progress(Hazard, Tick), FillHeight, FillColor);
106		}
107	}
108	
109	void AJamEffectsView::DrawSwing(const FJamEvent& Event, const FJamFighter& Self, const FVector2D& Pos, float Age)
110	{
111		const int32 Strike = FMath::RoundToInt32(Event.Amount);
112		const bool bFinisher = Strike >= 3;
113		// The strikes of a series go left, right, and across again for the finisher.
114		const float Side = Strike == 2 ? -1.f : 1.f;
115		const float Length = KatanaRange * (bFinisher ? FinisherScale : 1.f);
116		const double Yaw =
117			FMath::RadiansToDegrees(FMath::Atan2(Self.Facing.Y, Self.Facing.X)) + Side * FMath::Lerp(-KatanaHalfArc, KatanaHalfArc, Age);
118		const FVector2D Along = FVector2D(1.0, 0.0).GetRotated(Yaw);
119		const FVector2D Middle = Pos + Along * (0.5 * Length);
120		const FLinearColor Color = bFinisher ? FinisherColor : (Event.Side == EJamSide::Hero ? HeroBladeColor : BossBladeColor);
121	
122		UStaticMeshComponent& Blade = Take(JamShapes::Cube(), Color);
123		Blade.SetWorldLocationAndRotation(FVector(Middle.X, Middle.Y, BladeHeight), FRotator(0.0, Yaw, 0.0));
124		Blade.SetWorldScale3D(FVector(Length, BladeWidth * (bFinisher ? FinisherScale : 1.f), BladeThickness) / JamShapes::UnitSize);
125	}
126	
127	void AJamEffectsView::DrawTrail(const FJamEvent& Event, const FJamFighter& Self, const FVector2D& Pos)
128	{
129		const FVector2D Path = Pos - Event.Pos;
130		const double Length = Path.Size();
131		if (Length < 1.0)
132		{
133			return;
134		}
135		const FVector2D Middle = Event.Pos + 0.5 * Path;
136		const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Path.Y, Path.X));
137		UStaticMeshComponent& Trail = Take(JamShapes::Cube(), Event.Side == EJamSide::Hero ? HeroTrailColor : BossTrailColor);
138		Trail.SetWorldLocationAndRotation(FVector(Middle.X, Middle.Y, TrailHeight), FRotator(0.0, Yaw, 0.0));
139		Trail.SetWorldScale3D(FVector(Length, 2.f * Self.Radius, GroundThickness) / JamShapes::UnitSize);
140	}
141	
142	void AJamEffectsView::DrawBurst(const FJamEvent& Event, const FJamFight& Fight, float Alpha, float Age)
143	{
144		const FJamFighter& Self = Fight.Fighters[Event.Side];
145		const FVector2D SelfPos = FMath::Lerp(Self.PrevPos, Self.Pos, static_cast<double>(Alpha));
146		switch (Event.Type)
147		{
148			case EJamEvent::Swing:
