#pragma once

#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "GameFramework/HUD.h"

#include "JamHUD.generated.h"

/**
 * The prototype HUD, drawn on the canvas: the health of both fighters, what each button does now, the key hints, a
 * crosshair, the steal card and the title a fight ends with. Its words live in JamTexts. It reads the fight from the simulation host; what depends on the camera is
 * pushed in by the game mode.
 */
UCLASS()
class JAMGAME_API AJamHUD : public AHUD
{
	GENERATED_BODY()

public:
	virtual void DrawHUD() override;

	/** True in the mouse-look cameras, where the aim is the centre of the screen. */
	bool bCrosshair = false;

	/** Name of the active camera, shown next to the key hint. */
	FString CameraLabel;

private:
	void DrawBar(float X, float Y, float Width, float Height, float Fraction, const FLinearColor& Color);

	/** One line per button: what it does for the hero now, and what the Publisher took from it. */
	void DrawLoadout(const FJamLedger& Ledger, float X, float Bottom);

	/** A line of small text at the right edge; rows count up from the bottom one. */
	void DrawHint(const FString& Text, int32 Row);

	/** What the phase of the fight puts over the screen: the steal card, the stun call or an ending. */
	void DrawPhase(const FJamFight& Fight);

	/** The Publisher's grab: the options side by side, the key of each and the time left to answer. */
	void DrawStealCard(const FJamFight& Fight);

	/** The boss is down and everything is back: the call for the final blow. */
	void DrawStun();

	/** The title over the screen once the fight is over. */
	void DrawEnding(bool bWon);

	void DrawCentered(const FString& Text, float Y, float Scale, const FLinearColor& Color);
};

#include "UI/JamHUD.h"

#include "Engine/Canvas.h"
#include "Engine/Engine.h"
#include "Sim/JamFightSubsystem.h"
#include "Sim/JamLoadoutRules.h"
#include "Sim/JamStealRules.h"
#include "UI/JamTexts.h"

namespace
{
// Layout of the prototype HUD as fractions of the screen: presentation only, replaced by Kirill's UI in block E.
constexpr float BossBarWidth = 0.5f;
constexpr float BossBarTop = 0.04f;
constexpr float HeroBarWidth = 0.22f;
constexpr float HeroBarBottom = 0.93f;
constexpr float BarHeight = 0.022f;
constexpr float HudMargin = 0.03f;
constexpr float CrosshairSize = 4.f;
constexpr float TextScale = 1.4f;
constexpr float HintRowHeight = 20.f;
constexpr float LoadoutRowHeight = 24.f;
constexpr float LoadoutScale = 1.2f;
constexpr float LoadoutNameOffset = 70.f;
constexpr float EndingBandTop = 0.36f;
constexpr float EndingBandHeight = 0.24f;
constexpr float EndingTitleScale = 3.2f;
// The steal card: a band across the screen with the options side by side and the timer under them.
constexpr float CardTop = 0.24f;
constexpr float CardHeight = 0.46f;
constexpr float CardTitleScale = 2.8f;
constexpr float CardAskRow = 0.09f;
constexpr float CardOptionRow = 0.16f;
constexpr float CardOptionWidth = 0.2f;
constexpr float CardOptionHeight = 0.14f;
constexpr float CardOptionGap = 0.03f;
constexpr float CardOptionEdge = 4.f;
constexpr float CardPadding = 14.f;
constexpr float CardNameScale = 2.4f;
constexpr float CardNameRow = 0.055f;
constexpr float CardTimerRow = 0.34f;
constexpr float CardTimerHeight = 0.008f;
constexpr float CardHintRow = 0.37f;
constexpr float StunBandTop = 0.14f;
constexpr float StunBandHeight = 0.13f;
const FLinearColor BarBackColor(0.f, 0.f, 0.f, 0.6f);
const FLinearColor BossBarColor(0.9f, 0.15f, 0.15f);
const FLinearColor HeroBarColor(0.2f, 0.9f, 1.0f);
const FLinearColor StolenColor(1.0f, 0.35f, 0.3f);
const FLinearColor EndingBandColor(0.f, 0.f, 0.f, 0.75f);
const FLinearColor WinColor(1.0f, 0.3f, 0.85f);
const FLinearColor LockedColor(0.45f, 0.45f, 0.45f);

/** A button of the hero, the mechanic that lives on it and the name of the key. */
struct FLoadoutRow
{
	EJamButton Button;
	EJamMechanic Mechanic;
	const TCHAR* Key;
};

const FLoadoutRow LoadoutRows[] = {
	{ EJamButton::Primary, EJamMechanic::Katana, TEXT("LMB") },
	{ EJamButton::Secondary, EJamMechanic::Shuriken, TEXT("RMB") },
	{ EJamButton::Dash, EJamMechanic::Dash, TEXT("SPACE") },
};

/** What stands over an option of the card: the key that gives it away, or the mark of a cut nobody asks about. */
const TCHAR* OptionKey(const FJamStealState& Steal, int32 Index)
{
	if (Steal.bTakesAll)
	{
		return JamTexts::StealAllMark;
	}
	return Index == 0 ? JamTexts::StealLeftKey : JamTexts::StealRightKey;
}
} // namespace

void AJamHUD::DrawBar(float X, float Y, float Width, float Height, float Fraction, const FLinearColor& Color)
{
	DrawRect(BarBackColor, X, Y, Width, Height);
	DrawRect(Color, X, Y, Width * FMath::Clamp(Fraction, 0.f, 1.f), Height);
}

void AJamHUD::DrawLoadout(const FJamLedger& Ledger, float X, float Bottom)
{
	UFont* Font = GEngine->GetMediumFont();
	const int32 RowCount = UE_ARRAY_COUNT(LoadoutRows);
	for (int32 Index = 0; Index < RowCount; ++Index)
	{
		const FLoadoutRow& Row = LoadoutRows[Index];
		const float Y = Bottom - (RowCount - Index) * LoadoutRowHeight;
		const TCHAR* Name = JamLoadoutRules::Name(Row.Mechanic);
		if (Ledger.Has(EJamSide::Hero, Row.Mechanic))
		{
			DrawText(Row.Key, HeroBarColor, X, Y, Font, LoadoutScale);
			DrawText(Name, HeroBarColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
			continue;
		}
		const bool bBall = JamLoadoutRules::ActionFor(Row.Button, EJamSide::Hero, Ledger) == EJamAction::Ball;
		DrawText(Row.Key, StolenColor, X, Y, Font, LoadoutScale);
		DrawText(JamTexts::LoadoutStolen(bBall, Name), StolenColor, X + LoadoutNameOffset, Y, Font, LoadoutScale);
	}
}

void AJamHUD::DrawHint(const FString& Text, int32 Row)
{
	UFont* Font = GEngine->GetMediumFont();
	float Width = 0.f;
	float Height = 0.f;
	GetTextSize(Text, Width, Height, Font, 1.f);
	DrawText(Text, FLinearColor::White, (1.f - HudMargin) * Canvas->ClipX - Width, HeroBarBottom * Canvas->ClipY - Row * HintRowHeight,
		Font, 1.f);
}

void AJamHUD::DrawCentered(const FString& Text, float Y, float Scale, const FLinearColor& Color)
{
	UFont* Font = GEngine->GetMediumFont();
	float Width = 0.f;
	float Height = 0.f;
	GetTextSize(Text, Width, Height, Font, Scale);
	DrawText(Text, Color, 0.5f * (Canvas->ClipX - Width), Y, Font, Scale);
}

void AJamHUD::DrawStealCard(const FJamFight& Fight)
{
	const FJamStealState& Steal = Fight.Steal;
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	const float Top = CardTop * H;
	UFont* Font = GEngine->GetMediumFont();
	DrawRect(EndingBandColor, 0.f, Top, W, CardHeight * H);
	DrawCentered(Steal.bTakesAll ? JamTexts::StealAllTitle : JamTexts::StealTitle, Top + 0.02f * H, CardTitleScale, StolenColor);
	DrawCentered(Steal.bTakesAll ? JamTexts::StealAllAsk : JamTexts::StealAsk, Top + CardAskRow * H, TextScale, FLinearColor::White);

	// The options stay dim until the card takes an answer: a key held from the fight must not look like a choice.
	const FLinearColor Color = Fight.Tick >= Steal.OpenTick ? HeroBarColor : LockedColor;
	const float OptionWidth = CardOptionWidth * W;
	const float Gap = CardOptionGap * W;
	const int32 Count = Steal.Offer.Num();
	const float Left = 0.5f * (W - Count * OptionWidth - (Count - 1) * Gap);
	const float OptionTop = Top + CardOptionRow * H;
	for (int32 Index = 0; Index < Count; ++Index)
	{
		const float X = Left + Index * (OptionWidth + Gap);
		DrawRect(BarBackColor, X, OptionTop, OptionWidth, CardOptionHeight * H);
		DrawRect(Color, X, OptionTop, OptionWidth, CardOptionEdge);
		DrawText(OptionKey(Steal, Index), Color, X + CardPadding, OptionTop + CardPadding, Font, TextScale);
		DrawText(JamLoadoutRules::Name(Steal.Offer[Index]), Color, X + CardPadding, OptionTop + CardNameRow * H, Font, CardNameScale);
	}

	const float TimerWidth = 2.f * OptionWidth + Gap;
	const float TimeLeft = JamStealRules::TimeLeft(Steal, static_cast<float>(Fight.Tick));
	DrawBar(0.5f * (W - TimerWidth), Top + CardTimerRow * H, TimerWidth, CardTimerHeight * H, TimeLeft, StolenColor);
	DrawCentered(Steal.bTakesAll ? JamTexts::StealAllKey : JamTexts::StealDefault, Top + CardHintRow * H, TextScale, FLinearColor::White);
}

void AJamHUD::DrawStun()
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	DrawRect(EndingBandColor, 0.f, StunBandTop * H, W, StunBandHeight * H);
	DrawCentered(JamTexts::StunTitle, (StunBandTop + 0.015f) * H, CardTitleScale, WinColor);
	DrawCentered(JamTexts::StunAsk, (StunBandTop + 0.085f) * H, TextScale, FLinearColor::White);
}

void AJamHUD::DrawEnding(bool bWon)
{
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	DrawRect(EndingBandColor, 0.f, EndingBandTop * H, W, EndingBandHeight * H);
	DrawCentered(bWon ? JamTexts::WinTitle : JamTexts::LossTitle, (EndingBandTop + 0.06f) * H, EndingTitleScale,
		bWon ? WinColor : FLinearColor::White);
	DrawCentered(bWon ? JamTexts::WinHint : JamTexts::LossHint, (EndingBandTop + 0.17f) * H, TextScale, FLinearColor::White);
}

void AJamHUD::DrawPhase(const FJamFight& Fight)
{
	switch (Fight.Phase)
	{
		case EJamPhase::Steal:
			DrawStealCard(Fight);
			break;
		case EJamPhase::Stunned:
			DrawStun();
			break;
		case EJamPhase::HeroDead:
		case EJamPhase::Won:
			DrawEnding(Fight.Phase == EJamPhase::Won);
			break;
		default:
			break;
	}
}

void AJamHUD::DrawHUD()
{
	Super::DrawHUD();
	const UJamFightSubsystem* Host = GetWorld()->GetSubsystem<UJamFightSubsystem>();
	if (!Canvas || !Host)
	{
		return;
	}
	const float W = Canvas->ClipX;
	const float H = Canvas->ClipY;
	UFont* Font = GEngine->GetMediumFont();
	const FJamFight& Fight = Host->GetFight();
	const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
	const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];

	const float BossX = 0.5f * (1.f - BossBarWidth) * W;
	DrawBar(BossX, BossBarTop * H, BossBarWidth * W, BarHeight * H, Boss.Health / FMath::Max(1.f, Boss.MaxHealth), BossBarColor);
	const FString BossText = JamTexts::BossHealth(FMath::CeilToInt32(Boss.Health), FMath::CeilToInt32(Boss.MaxHealth));
	DrawText(BossText, FLinearColor::White, BossX, (BossBarTop + BarHeight) * H + 4.f, Font, TextScale);

	DrawBar(HudMargin * W, HeroBarBottom * H, HeroBarWidth * W, BarHeight * H, Hero.Health / FMath::Max(1.f, Hero.MaxHealth), HeroBarColor);
	const float HeroTextY = HeroBarBottom * H - 28.f;
	DrawText(JamTexts::HeroHealth(FMath::CeilToInt32(Hero.Health)), FLinearColor::White, HudMargin * W, HeroTextY, Font, TextScale);
	DrawLoadout(Fight.Ledger, HudMargin * W, HeroTextY - 6.f);

	DrawHint(JamTexts::CameraHint(CameraLabel), 0);
	DrawHint(JamTexts::DebugHint, 1);

	if (bCrosshair)
	{
		DrawRect(FLinearColor::White, 0.5f * W - 0.5f * CrosshairSize, 0.5f * H - 0.5f * CrosshairSize, CrosshairSize, CrosshairSize);
	}
	DrawPhase(Fight);
}

#pragma once

#include "CoreMinimal.h"

/**
 * Every line of text the player reads on the prototype HUD, in one place: the voice of the game is edited here and
 * nowhere else. Names of the mechanics live with the mechanics, in JamLoadoutRules::Name.
 */
namespace JamTexts
{
// The steal card.
inline const TCHAR* const StealTitle = TEXT("THE PUBLISHER HAS NOTES");
inline const TCHAR* const StealAsk = TEXT("Two features are on his desk. Give one away: he will use it against you.");
inline const TCHAR* const StealLeftKey = TEXT("[A]");
inline const TCHAR* const StealRightKey = TEXT("[D]");
inline const TCHAR* const StealDefault = TEXT("No answer: he takes the left one.");
inline const TCHAR* const StealAllTitle = TEXT("FINAL NOTE: CUT THE REST");
inline const TCHAR* const StealAllAsk = TEXT("He takes what you have left. You keep the ball.");
inline const TCHAR* const StealAllMark = TEXT("CUT");
inline const TCHAR* const StealAllKey = TEXT("[A] hand it over");

// The stun before the final blow.
inline const TCHAR* const StunTitle = TEXT("HE IS OUT OF NOTES");
inline const TCHAR* const StunAsk = TEXT("Everything is yours again. Land the final blow.");

// The endings.
inline const TCHAR* const WinTitle = TEXT("NEON RONIN: DIRECTOR'S CUT");
inline const TCHAR* const WinHint = TEXT("The Publisher is out of the building.   R: play again");
inline const TCHAR* const LossTitle = TEXT("SHIPPED AS PROOF OF CONCEPT");
inline const TCHAR* const LossHint = TEXT("The Publisher shipped it without you.   R: retry from the last cut");

inline const TCHAR* const DebugHint = TEXT("Debug: F5 skip to the next cut   F6 restart the fight");

inline FString BossHealth(int32 Now, int32 Max)
{
	return FString::Printf(TEXT("THE PUBLISHER  %d / %d"), Now, Max);
}

inline FString HeroHealth(int32 Now)
{
	return FString::Printf(TEXT("RONIN  %d"), Now);
}

/** What a button is left with after a steal: the weak ball on the attack buttons, nothing on the dash. */
inline FString LoadoutStolen(bool bBall, const TCHAR* Mechanic)
{
	return FString::Printf(TEXT("%s    (%s is the Publisher's now)"), bBall ? TEXT("BALL") : TEXT("nothing"), Mechanic);
}

inline FString CameraHint(const FString& Camera)
{
	return FString::Printf(TEXT("Camera: %s    F1 top-down   F2 shoulder   F3 first person"), *Camera);
}
} // namespace JamTexts

#include "View/JamEffectsView.h"

#include "Components/StaticMeshComponent.h"
#include "Sim/JamHazardRules.h"
#include "View/JamShapes.h"

namespace
{
// Greybox look of the effects: presentation only. Lives are in seconds, sizes in cm.
constexpr float SwingLife = 0.16f;
constexpr float ExplosionLife = 0.2f;
constexpr float SlamLife = 0.25f;
constexpr float TrailLife = 0.22f;
constexpr float BladeHeight = 110.f;
constexpr float BladeWidth = 16.f;
constexpr float BladeThickness = 6.f;
constexpr float FinisherScale = 1.25f;
constexpr float GroundThickness = 2.f;
// Flat shapes lie in layers a little above the floor so they do not flicker through each other.
constexpr float CircleHeight = 3.f;
constexpr float FillHeight = 5.f;
constexpr float FlashHeight = 7.f;
constexpr float TrailHeight = 4.f;
constexpr float ExplosionStartSize = 0.4f;
const FLinearColor CircleColor(0.22f, 0.02f, 0.03f);
const FLinearColor FillColor(1.0f, 0.12f, 0.1f);
const FLinearColor SlamColor(1.0f, 0.85f, 0.7f);
const FLinearColor ExplosionColor(1.0f, 0.55f, 0.08f);
const FLinearColor HeroBladeColor(0.75f, 1.0f, 1.0f);
const FLinearColor BossBladeColor(1.0f, 0.45f, 0.3f);
const FLinearColor FinisherColor(1.0f, 0.3f, 0.85f);
const FLinearColor HeroTrailColor(0.05f, 0.35f, 0.5f);
const FLinearColor BossTrailColor(0.4f, 0.06f, 0.06f);

/** The stage was cleared by this event: whatever hangs in the air belongs to the fight before it. */
bool ClearsTheAir(EJamEvent Type)
{
	return Type == EJamEvent::StealOpened || Type == EJamEvent::Stunned;
}
} // namespace

float AJamEffectsView::LifeOf(const FJamEvent& Event) const
{
	switch (Event.Type)
	{
		case EJamEvent::Swing:
			return Event.Side == EJamSide::Boss ? BossSwingLife : SwingLife;
		case EJamEvent::Explosion:
			return ExplosionLife;
		case EJamEvent::Slam:
			return SlamLife;
		case EJamEvent::Dash:
			return TrailLife;
		default:
			return 0.f;
	}
}

AJamEffectsView::AJamEffectsView()
{
	PrimaryActorTick.bCanEverTick = false;
	SetRootComponent(CreateDefaultSubobject<USceneComponent>(TEXT("Root")));
	// The pool is filled at runtime: the shapes have to be found here, in a constructor.
	JamShapes::Cylinder();
	JamShapes::Cube();
	JamShapes::Material();
}

void AJamEffectsView::Init(const FJamBalanceData& Balance)
{
	KatanaRange = Balance.KatanaRange;
	KatanaHalfArc = Balance.KatanaHalfArc;
	BossSwingLife = Balance.BossKatanaWindUp;
}

UStaticMeshComponent& AJamEffectsView::Take(UStaticMesh* Mesh, const FLinearColor& Color)
{
	if (Used == Pool.Num())
	{
		UStaticMeshComponent* Shape = NewObject<UStaticMeshComponent>(this);
		JamShapes::Setup(*Shape, Mesh);
		Shape->SetupAttachment(RootComponent);
		Shape->RegisterComponent();
		Pool.Add(Shape);
	}
	UStaticMeshComponent& Shape = *Pool[Used++];
	if (Shape.GetStaticMesh() != Mesh)
	{
		Shape.SetStaticMesh(Mesh);
	}
	Shape.SetVisibility(true);
	JamShapes::Paint(Shape, Color);
	return Shape;
}

void AJamEffectsView::DrawDisc(const FVector2D& Pos, float Radius, float Height, const FLinearColor& Color)
{
	UStaticMeshComponent& Disc = Take(JamShapes::Cylinder(), Color);
	Disc.SetWorldLocationAndRotation(FVector(Pos.X, Pos.Y, Height), FRotator::ZeroRotator);
	Disc.SetWorldScale3D(FVector(2.f * Radius, 2.f * Radius, GroundThickness) / JamShapes::UnitSize);
}

void AJamEffectsView::DrawCircles(const FJamFight& Fight, float Alpha)
{
	// Fight.Tick is the step to come: the picture is between the two before it.
	const float Tick = Fight.Tick - 1.f + Alpha;
	for (const FJamHazard& Hazard : Fight.Hazards)
	{
		DrawDisc(Hazard.Pos, Hazard.Radius, CircleHeight, CircleColor);
		// The fill grows to the edge of the circle exactly when it hits: the player reads the time left from it.
		DrawDisc(Hazard.Pos, Hazard.Radius * JamHazardRules::Progress(Hazard, Tick), FillHeight, FillColor);
	}
}

void AJamEffectsView::DrawSwing(const FJamEvent& Event, const FJamFighter& Self, const FVector2D& Pos, float Age)
{
	const int32 Strike = FMath::RoundToInt32(Event.Amount);
	const bool bFinisher = Strike >= 3;
	// The strikes of a series go left, right, and across again for the finisher.
	const float Side = Strike == 2 ? -1.f : 1.f;
	const float Length = KatanaRange * (bFinisher ? FinisherScale : 1.f);
	const double Yaw =
		FMath::RadiansToDegrees(FMath::Atan2(Self.Facing.Y, Self.Facing.X)) + Side * FMath::Lerp(-KatanaHalfArc, KatanaHalfArc, Age);
	const FVector2D Along = FVector2D(1.0, 0.0).GetRotated(Yaw);
	const FVector2D Middle = Pos + Along * (0.5 * Length);
	const FLinearColor Color = bFinisher ? FinisherColor : (Event.Side == EJamSide::Hero ? HeroBladeColor : BossBladeColor);

	UStaticMeshComponent& Blade = Take(JamShapes::Cube(), Color);
	Blade.SetWorldLocationAndRotation(FVector(Middle.X, Middle.Y, BladeHeight), FRotator(0.0, Yaw, 0.0));
	Blade.SetWorldScale3D(FVector(Length, BladeWidth * (bFinisher ? FinisherScale : 1.f), BladeThickness) / JamShapes::UnitSize);
}

void AJamEffectsView::DrawTrail(const FJamEvent& Event, const FJamFighter& Self, const FVector2D& Pos)
{
	const FVector2D Path = Pos - Event.Pos;
	const double Length = Path.Size();
	if (Length < 1.0)
	{
		return;
	}
	const FVector2D Middle = Event.Pos + 0.5 * Path;
	const double Yaw = FMath::RadiansToDegrees(FMath::Atan2(Path.Y, Path.X));
	UStaticMeshComponent& Trail = Take(JamShapes::Cube(), Event.Side == EJamSide::Hero ? HeroTrailColor : BossTrailColor);
	Trail.SetWorldLocationAndRotation(FVector(Middle.X, Middle.Y, TrailHeight), FRotator(0.0, Yaw, 0.0));
	Trail.SetWorldScale3D(FVector(Length, 2.f * Self.Radius, GroundThickness) / JamShapes::UnitSize);
}

void AJamEffectsView::DrawBurst(const FJamEvent& Event, const FJamFight& Fight, float Alpha, float Age)
{
	const FJamFighter& Self = Fight.Fighters[Event.Side];
	const FVector2D SelfPos = FMath::Lerp(Self.PrevPos, Self.Pos, static_cast<double>(Alpha));
	switch (Event.Type)
	{
		case EJamEvent::Swing:
			DrawSwing(Event, Self, SelfPos, Age);
			break;
		case EJamEvent::Explosion:
			DrawDisc(Event.Pos, Event.Amount * FMath::Lerp(ExplosionStartSize, 1.f, Age), FlashHeight, ExplosionColor);
			break;
		case EJamEvent::Slam:
			DrawDisc(Event.Pos, Event.Amount, FlashHeight, SlamColor);
			break;
		case EJamEvent::Dash:
			DrawTrail(Event, Self, SelfPos);
			break;
		default:
			break;
	}
}

void AJamEffectsView::Sync(const FJamFight& Fight, const TArray<FJamEvent>& Events, float Alpha, float Time)
{
	for (const FJamEvent& Event : Events)
	{
		const float Life = LifeOf(Event);
		if (ClearsTheAir(Event.Type))
		{
			Bursts.Reset();
		}
		else if (Life > 0.f)
		{
			Bursts.Add({ Event, Time, Life });
		}
	}
	Used = 0;
	DrawCircles(Fight, Alpha);
	for (int32 Index = Bursts.Num() - 1; Index >= 0; --Index)
	{
		const float Age = (Time - Bursts[Index].StartTime) / Bursts[Index].Life;
		if (Age >= 1.f)
		{
			Bursts.RemoveAtSwap(Index);
			continue;
		}
		DrawBurst(Bursts[Index].Event, Fight, Alpha, Age);
	}
	for (int32 Index = Used; Index < Pool.Num(); ++Index)
	{
		Pool[Index]->SetVisibility(false);
	}
}

#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"
#include "GameFramework/Actor.h"

#include "JamEffectsView.generated.h"

class UStaticMesh;
class UStaticMeshComponent;

/**
 * What a fight leaves in the air for a moment: the warning circles, the sweep of a katana, the flash of an explosion or
 * of a slam, the trail of a dash. Greybox shapes from a pool that only grows; the events of the simulation start the
 * effects, the world clock ends them.
 */
UCLASS()
class JAMGAME_API AJamEffectsView : public AActor
{
	GENERATED_BODY()

public:
	AJamEffectsView();

	/** Takes the reach, the arc and the timing of the katana from the balance numbers, so the blade shows what really hits. */
	void Init(const FJamBalanceData& Balance);

	/** Starts the effects of the frame's events and draws everything that is alive at Time. */
	void Sync(const FJamFight& Fight, const TArray<FJamEvent>& Events, float Alpha, float Time);

private:
	/** A short effect started by an event. */
	struct FBurst
	{
		FJamEvent Event;
		float StartTime = 0.f;
		/** Seconds it stays on screen. */
		float Life = 0.f;
	};

	/** Seconds the effect of an event lasts; 0 for the events that are not drawn here. */
	float LifeOf(const FJamEvent& Event) const;

	/** The next free shape of the pool, shown, with this mesh and colour. */
	UStaticMeshComponent& Take(UStaticMesh* Mesh, const FLinearColor& Color);

	void DrawDisc(const FVector2D& Pos, float Radius, float Height, const FLinearColor& Color);
	void DrawCircles(const FJamFight& Fight, float Alpha);
	/** Age runs from 0 to 1 over the life of the effect. */
	void DrawBurst(const FJamEvent& Event, const FJamFight& Fight, float Alpha, float Age);
	void DrawSwing(const FJamEvent& Event, const FJamFighter& Self, const FVector2D& Pos, float Age);
	void DrawTrail(const FJamEvent& Event, const FJamFighter& Self, const FVector2D& Pos);

	UPROPERTY()
	TArray<TObjectPtr<UStaticMeshComponent>> Pool;

	TArray<FBurst> Bursts;
	int32 Used = 0;
	float KatanaRange = 0.f;
	float KatanaHalfArc = 0.f;
	/** The Publisher's blade sweeps through his whole wind-up: the sweep is the warning. */
	float BossSwingLife = 0.f;
};

