- Done in block B: `JamBotRules::Play` (uses whatever the hero still owns, dashes out of warning circles and away
  from projectiles about to hit, closes in while the boss is busy), tests `Jam.Bot.LeavesTheSlamCircle`,
  `DivesInWhileTheBossRecovers`, `DashesThroughAMemo`, `HoldsItsOwnAgainstThePublisher`. The demo run plays with it.
- Measured in block B: the bot beats the Publisher in about 12 seconds, the target is 3 to 4 minutes. The balance
  pass belongs to block C, with the fight length as a test.
- Left: steal policies, the headless runner and the tests below.

## Test seam

- `Jam.Bot.FightAlwaysEnds`: 20 seeds, every fight ends as `Won` or `HeroDead` within the time limit.
- `Jam.Bot.EveryStealOrderIsWinnable`: for each order of giving mechanics away at least one seed in N is a win.
- `Jam.Bot.FightLengthIsInRange`: the median duration is between 2 and 5 minutes (target 3 to 4).
- `Jam.Bot.SameSeedSameFight`: the simulation is deterministic.

## Done

Tests green; the numbers in the balance section are tuned until they are. The table of results goes to `DEVLOG.md`.
#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/**
 * A bot that plays a fighter through the same intent a person writes. It drives the hero in clips and in full-fight
 * tests, so a fight can be watched and checked without hands on the keyboard.
 * Tests: Jam.Bot.*
 */
namespace JamBotRules
{
/** Circles the opponent at Range and keeps shooting at it. */
JAMGAME_API FJamIntent Kite(const FJamFight& Fight, EJamSide Side, float Range);

/**
 * Plays the hero against the Publisher with whatever he still owns: keeps out of the slam range and throws from there,
 * runs in with the katana while the boss stands after an attack, leaves the warning circles and dashes through the
 * memos that are about to hit.
 */
JAMGAME_API FJamIntent Play(const FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance);
} // namespace JamBotRules
#include "Sim/JamBotRules.h"

#include "Sim/JamBossRules.h"

namespace
{
// Share of the range over which the bot goes from "hold the distance" to a full run in or out.
constexpr float RangeSoftness = 0.25f;
// The bot holds its distance at this share of the slam range: too far to be slammed, close enough to run in.
constexpr float RangeOverSlam = 1.5f;
// How far outside a warning circle the bot wants to be before it stops running.
constexpr float CircleMargin = 30.f;
// A projectile that arrives sooner than this is dodged with the dash.
constexpr float DodgeSeconds = 0.15f;
constexpr float DodgeMargin = 10.f;

/** The enemy's warning circle the fighter stands in, if there is one. */
const FJamHazard* CircleOver(const FJamFight& Fight, EJamSide Side)
{
	const FVector2D Pos = Fight.Fighters[Side].Pos;
	for (const FJamHazard& Hazard : Fight.Hazards)
	{
		if (Hazard.Owner != Side && FVector2D::Distance(Hazard.Pos, Pos) < Hazard.Radius + CircleMargin)
		{
			return &Hazard;
		}
	}
	return nullptr;
}

/** True when an enemy projectile reaches the fighter within the dodge time if he stays where he is. */
bool IsAboutToBeHit(const FJamFight& Fight, EJamSide Side)
{
	const FJamFighter& Me = Fight.Fighters[Side];
	for (const FJamProjectile& Flying : Fight.Projectiles)
	{
		if (Flying.Owner == Side)
		{
			continue;
		}
		const FVector2D Closest = FMath::ClosestPointOnSegment2D(Me.Pos, Flying.Pos, Flying.Pos + Flying.Vel * DodgeSeconds);
		if (FVector2D::Distance(Closest, Me.Pos) < Me.Radius + Flying.Radius + DodgeMargin)
		{
			return true;
		}
	}
	return false;
}
} // namespace

FJamIntent JamBotRules::Kite(const FJamFight& Fight, EJamSide Side, float Range)
{
	const FJamFighter& Me = Fight.Fighters[Side];
	const FJamFighter& Target = Fight.Fighters[JamSim::Other(Side)];
	const FVector2D To = Target.Pos - Me.Pos;
	const double Distance = To.Size();
	const FVector2D Dir = Distance > UE_KINDA_SMALL_NUMBER ? To / Distance : Me.Facing;
	const FVector2D Sideways(-Dir.Y, Dir.X);
	const double Radial = FMath::Clamp((Distance - Range) / (Range * RangeSoftness), -1.0, 1.0);

	FJamIntent Intent;
	Intent.Move = (Dir * Radial + Sideways).GetSafeNormal();
	Intent.Aim.Dir = Dir;
	Intent.Aim.Point = Target.Pos;
	Intent.bPrimary = true;
	return Intent;
}

FJamIntent JamBotRules::Play(const FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
{
	const FJamFighter& Me = Fight.Fighters[Side];
	const FJamFighter& Target = Fight.Fighters[JamSim::Other(Side)];
	const bool bHasKatana = Fight.Ledger.Has(Side, EJamMechanic::Katana);
	const bool bInReach = FVector2D::Distance(Me.Pos, Target.Pos) <= Balance.KatanaRange + Target.Radius;

	FJamIntent Intent = Kite(Fight, Side, Balance.SlamRange * RangeOverSlam);
	// The katana is not swung at the air; the ball on the same button is shot from anywhere.
	Intent.bPrimary = !bHasKatana || bInReach;
	Intent.bSecondary = true;
	Intent.bDash = IsAboutToBeHit(Fight, Side);
	if (const FJamHazard* Circle = CircleOver(Fight, Side))
	{
		// Out of the circle first, by the shortest way; from its very centre any way is as good, so away from the enemy.
		const FVector2D Away = Me.Pos - Circle->Pos;
		Intent.Move = Away.IsNearlyZero() ? -Intent.Aim.Dir : Away.GetSafeNormal();
		Intent.bDash = true;
	}
	else if (bHasKatana && Side == EJamSide::Hero && JamBossRules::IsBusy(Fight))
	{
		// The boss stands after his attack: this is when the katana pays.
		Intent.Move = Intent.Aim.Dir;
	}
	return Intent;
}
