	const FVector2D Pos = JamMoveRules::PushOut(Self.Pos + Delta, Self.Radius, Other.Pos, Other.Radius);
	Self.Pos = JamMoveRules::ClampToArena(Pos, Self.Radius, ArenaRadius);
}
