66	
67	FJamIntent JamBossRules::Decide(const FJamFight& Fight, const FJamBalanceData& Balance)
68	{
69		const FJamFighter& Boss = Fight.Fighters[EJamSide::Boss];
70		const FJamFighter& Hero = Fight.Fighters[EJamSide::Hero];
71		const FVector2D To = Hero.Pos - Boss.Pos;
72		const double Distance = To.Size();
73	
74		FJamIntent Intent;
75		Intent.Aim.Dir = Distance > UE_KINDA_SMALL_NUMBER ? To / Distance : Boss.Facing;
76		Intent.Aim.Point = Hero.Pos;
77		if (Fight.Phase != EJamPhase::Fight || IsBusy(Fight))
78		{
79			return Intent;
80		}
81		if (WantsToDash(Fight, Distance, Balance, Intent))
82		{
83			return Intent;
84		}
85		const bool bInBladeReach = Distance <= Balance.KatanaRange + Hero.Radius;
86		// One attack of his own at a time, the slam first: a hero who came close must pay attention.
87		if (Distance <= Balance.SlamRange && Fight.Tick >= Fight.Boss.SlamReadyTick)
88		{
89			Intent.bSlam = true;
90		}
91		else if (bInBladeReach && Fight.Ledger.Has(EJamSide::Boss, EJamMechanic::Katana))
92		{
93			Intent.bPrimary = true;
94		}
95		else if (Fight.Tick >= Fight.Boss.VolleyReadyTick)
96		{
97			Intent.bVolley = true;
98		}
99		else if (Distance > Boss.Radius + Hero.Radius + 1.0)
100		{
101			Intent.Move = Intent.Aim.Dir;
102		}
103		// The stolen shuriken fills the gaps between his own attacks: it is thrown at a hero who keeps away.
104		Intent.bSecondary = !bInBladeReach && !Intent.bSlam && Fight.Ledger.Has(EJamSide::Boss, EJamMechanic::Shuriken);
105		return Intent;
106	}
107	
108	bool JamBossRules::IsBusy(const FJamFight& Fight)
109	{
110		// He also stands through the wind-up of the stolen katana: the slow blade is the warning.
111		return Fight.Phase == EJamPhase::Stunned || Fight.Tick < Fight.Boss.BusyUntilTick || Fight.Fighters[EJamSide::Boss].Katana.bHitPending;
112	}
113	
114	TArray<FVector2D> JamBossRules::VolleyDirections(const FVector2D& AimDir, int32 Count, float SpreadDeg)
115	{
116		TArray<FVector2D> Directions;
117		const FVector2D Dir = AimDir.GetSafeNormal();
118		for (int32 Index = 0; Index < Count; ++Index)
119		{
120			const float Angle = Count > 1 ? SpreadDeg * (static_cast<float>(Index) / (Count - 1) - 0.5f) : 0.f;
121			Directions.Add(Dir.GetRotated(Angle));
122		}
123		return Directions;

