139	{
140		const FJamFighter& Me = Fight.Fighters[Side];
141		const FJamFighter& Target = Fight.Fighters[JamSim::Other(Side)];
142		const bool bHasKatana = Fight.Ledger.Has(Side, EJamMechanic::Katana);
143		const bool bInReach = FVector2D::Distance(Me.Pos, Target.Pos) <= Balance.KatanaRange + Target.Radius;
144	
145		FJamIntent Intent = Kite(Fight, Side, Balance.SlamRange * RangeOverSlam);
146		Intent.Move = CircleMove(Fight, Side, Intent);
147		// The katana is not swung at the air; the ball on the same button is shot from anywhere.
