149		Intent.bSecondary = true;
150		Intent.bDash = IsAboutToBeHit(Fight, Side);
151		if (const FJamHazard* Circle = CircleOver(Fight, Side))
152		{
153			// Out of the circle first, by the shortest way; from its very centre any way is as good, so away from the enemy.
154			const FVector2D Away = Me.Pos - Circle->Pos;
155			Intent.Move = Away.IsNearlyZero() ? -Intent.Aim.Dir : Away.GetSafeNormal();
156			Intent.bDash = true;
157		}
158		else if (IsUnderTheBlade(Fight, Side, Balance))
159		{
160			// A slow blade is walked out of; the dash is for the one that is about to land.
