163		}
164		else if (bHasKatana && Fight.Ledger.Has(Side, EJamMechanic::Dash) && Side == EJamSide::Hero && JamBossRules::IsBusy(Fight))
165		{
166			// The boss stands after his attack: this is when the katana pays. Only with the dash in hand: next to him it is
167			// the one way through a volley.
