// DIAG-BEGIN (temporary, not for commit)
IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamBotDiagTest, "Jam.Bot.Diag", JamTest::Flags)

bool FJamBotDiagTest::RunTest(const FString& Parameters)
{
	const FJamBalanceData B = GameBalance();
	TMap<FString, int32> Tally;
	TMap<int32, int32> StageTicks;
	for (int32 Seed = 1; Seed <= 6; ++Seed)
	{
		FJamFight Fight = JamFightRules::Start(B, Seed);
		int32 Steps = 0;
		int32 Logged = 0;
		while (Steps < JamSim::Ticks(400.f) && Fight.Phase != EJamPhase::Won && Fight.Phase != EJamPhase::HeroDead)
		{
			FJamIntent Intent = JamBotRules::Play(Fight, EJamSide::Hero, B);
			Intent.Choice = JamBotRules::Choose(Fight, EJamStealPolicy::Left);
			const FJamFight Before = Fight;
			JamFightRules::Play(Fight, Intent, B);
			StageTicks.FindOrAdd(Fight.Steal.Done)++;
			for (const FJamEvent& Event : Fight.Events)
			{
				if (Event.Type != EJamEvent::Hit || Event.Side != EJamSide::Hero)
				{
					continue;
				}
				const bool bDash = Fight.Ledger.Has(EJamSide::Hero, EJamMechanic::Dash);
				Tally.FindOrAdd(FString::Printf(TEXT("stage %d dash %d amount %.1f"), Fight.Steal.Done, bDash ? 1 : 0, Event.Amount))++;
				if (Seed == 1 && !bDash && Logged < 12)
				{
					++Logged;
					const FJamFighter& Hero = Before.Fighters[EJamSide::Hero];
					const FJamFighter& Boss = Before.Fighters[EJamSide::Boss];
					const FVector2D Vel = (Hero.Pos - Hero.PrevPos) / JamSim::StepDt;
					AddInfo(FString::Printf(
						TEXT("diag hit | t %.1f | amount %.1f | dist %.0f | hero r %.0f | vel %.0f,%.0f | move %.2f,%.2f | shots %d"),
						Fight.Tick * JamSim::StepDt, Event.Amount, FVector2D::Distance(Hero.Pos, Boss.Pos), Hero.Pos.Size(), Vel.X, Vel.Y,
						Intent.Move.X, Intent.Move.Y, Before.Projectiles.Num()));
				}
			}
			++Steps;
		}
	}
	Tally.KeySort([](const FString& L, const FString& R) { return L < R; });
	for (const TPair<FString, int32>& Row : Tally)
	{
		AddInfo(FString::Printf(TEXT("diag tally | %s | %d"), *Row.Key, Row.Value));
	}
	for (const TPair<int32, int32>& Row : StageTicks)
	{
		AddInfo(FString::Printf(TEXT("diag stage | %d | %.0f s over 6 fights"), Row.Key, Row.Value * JamSim::StepDt));
	}
	return true;
}
// DIAG-END

#endif

