BOT_TEST = '''IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamBotWallTest, "Jam.Bot.KeepsOffTheWall", JamTest::Flags)

bool FJamBotWallTest::RunTest(const FString& Parameters)
{
	// T-033: what the Publisher throws past the hero ends on the wall, and an explosive shuriken goes off there. A bug
	// here looks in clips like "the bot hugs the wall and every blast behind it lands".
	const FJamBalanceData B = JamTest::Balance();
	const FVector2D Outward(-1.0, 0.0);
	const FVector2D AtTheWall = Outward * (B.ArenaRadius - B.HeroRadius);
	// The boss is closer than the bot likes: it wants to back off, and the wall is right behind it.
	FJamFight F = JamTest::Fight(B, AtTheWall, AtTheWall - Outward * B.SlamRange);
	F.Boss.BusyUntilTick = 0;
	const FJamIntent Pinned = JamBotRules::Play(F, EJamSide::Hero, B);
	TestTrue(TEXT("at the wall the bot turns back into the open"), FVector2D::DotProduct(Pinned.Move, Outward) < -0.1);
	TestTrue(TEXT("around the boss, not through him"), FMath::Abs(Pinned.Move.Y) > 0.1);
	TestTrue(TEXT("at full speed"), FMath::IsNearlyEqual(Pinned.Move.Size(), 1.0, 0.001));

	FJamFighter& Hero = F.Fighters[EJamSide::Hero];
	Hero.Pos = Hero.PrevPos = Outward * 100.0;
	F.Fighters[EJamSide::Boss].Pos = Hero.Pos - Outward * B.SlamRange;
	const FJamIntent Free = JamBotRules::Play(F, EJamSide::Hero, B);
	TestTrue(TEXT("in the open it backs off from him as before"), FVector2D::DotProduct(Free.Move, Outward) > 0.1);
	return true;
}

'''

OLD_HELPER_START = "/** The move without its push into the arena wall: at the wall the fighter runs along it at full speed. */\n"
OLD_HELPER_END = "/** True when an enemy projectile reaches the fighter within the dodge time if he stays where he is. */\n"
NEW_HELPER = '''/** The move with the arena wall in mind: the closer the wall, the more the fighter turns back into the open. */
FVector2D OffTheWall(const FJamFighter& Me, const FVector2D& Move, const FJamBalanceData& Balance)
{
	const double Room = WallRoomInBlasts * Balance.ShurikenExplosionRadius;
	const double FromCentre = Me.Pos.Size();
	// Nothing where the room begins, one where the fighter touches the wall.
	const double Depth = FMath::Min((FromCentre + Me.Radius + Room - Balance.ArenaRadius) / Room, 1.0);
	if (FromCentre < UE_KINDA_SMALL_NUMBER || Depth <= 0.0)
	{
		return Move;
	}
	const FVector2D Outward = Me.Pos / FromCentre;
	const FVector2D Pushed = (Move - Outward * (WallPush * Depth)).GetSafeNormal();
	return Pushed.IsNearlyZero() ? -Outward : Pushed;
}

'''

if sys.argv[1] == "tests":
    path = SRC / "Private/Tests/JamBotTest.cpp"
    text = path.read_text(encoding="utf-8")
    old = between(text, "IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamBotWallTest", "IMPLEMENT_SIMPLE_AUTOMATION_TEST(FJamBotBlastTest")
    path.write_text(text.replace(old, BOT_TEST), encoding="utf-8", newline="\n")
    print("patched the wall test")
else:
    path = SRC / "Private/Sim/JamBotRules.cpp"
    text = path.read_text(encoding="utf-8")
    old = between(text, OLD_HELPER_START, OLD_HELPER_END)
    text = text.replace(old, NEW_HELPER)
    pairs = [
        (
            "// Closer to the arena wall than this, the bot stops pushing into it.\nconstexpr float WallMargin = 5.f;\n",
            "// The room the bot keeps from the arena wall, in blast radii of a shuriken: what flies past it goes off there.\n"
            "constexpr float WallRoomInBlasts = 2.f;\n"
            "// How hard the wall turns the bot back at its very foot, against a move of length one.\n"
            "constexpr float WallPush = 2.f;\n",
        ),
        ("\tIntent.Move = AlongTheWall(Me, Intent.Move, Balance.ArenaRadius);\n", ""),
        (
            "\tIntent.Move = CircleMove(Fight, Side, Intent, Balance);\n",
            "\tIntent.Move = OffTheWall(Me, CircleMove(Fight, Side, Intent, Balance), Balance);\n",
        ),
    ]
    for old, new in pairs:
        assert text.count(old) == 1, (old[:60], text.count(old))
        text = text.replace(old, new)
    path.write_text(text, encoding="utf-8", newline="\n")
    print("patched the bot")

