1	#pragma once
2	
3	#include "CoreMinimal.h"
4	#include "Math/RandomStream.h"
5	
6	/**
7	 * Plain data of the fight simulation.
8	 *
9	 * The fight is flat: simulation X and Y are world X and Y, height exists only in the view. Nothing here knows about
10	 * actors, cameras or input devices: the hero and the boss are driven by the same FJamIntent, whoever writes it.
11	 */
12	
13	enum class EJamSide : uint8
14	{
15		Hero,
16		Boss
17	};
18	
19	/** The fixed step of the simulation. Every duration inside the simulation is a whole number of steps. */
20	namespace JamSim
21	{
22	inline constexpr int32 StepsPerSecond = 60;
23	inline constexpr float StepDt = 1.f / StepsPerSecond;
24	
25	/** Seconds from the balance data as steps, at least one. */
26	inline int32 Ticks(float Seconds)
27	{
28		return FMath::Max(1, FMath::RoundToInt32(Seconds * StepsPerSecond));
29	}
30	
31	inline EJamSide Other(EJamSide Side)
32	{
33		return Side == EJamSide::Hero ? EJamSide::Boss : EJamSide::Hero;
34	}
35	} // namespace JamSim
36	
37	/** One value for the hero and one for the boss. */
38	template <typename T>
39	struct TJamPerSide
40	{
41		T Items[2];
42	
43		T& operator[](EJamSide Side) { return Items[static_cast<int32>(Side)]; }
44	
45		const T& operator[](EJamSide Side) const { return Items[static_cast<int32>(Side)]; }
46	};
47	
48	/** Where a fighter aims. A zero Dir means "no aim this step": the fighter keeps its facing. */
49	struct FJamAim
50	{
51		FVector2D Dir = FVector2D::ZeroVector;
52		FVector2D Point = FVector2D::ZeroVector;
53	};
54	
55	/** What a fighter wants to do this step. Buttons are "held" states, the simulation decides when they fire. */
56	struct FJamIntent
57	{
58		/** World-space move direction, length up to 1. */
59		FVector2D Move = FVector2D::ZeroVector;
60		FJamAim Aim;
61		bool bPrimary = false;
62		bool bSecondary = false;
63		bool bDash = false;
64		/** The Publisher's own attacks. Nobody else has them, the hero's are ignored. */
65		bool bVolley = false;
66		bool bSlam = false;
67		/** Index of the picked option of the steal choice, -1 when nothing is picked. */
68		int32 Choice = -1;
69	};
70	
71	using FJamIntents = TJamPerSide<FJamIntent>;
72	
73	/** The mechanics that can change hands. Parry and Ultimate join in block D. */
74	enum class EJamMechanic : uint8
75	{
76		Katana,
77		Shuriken,
78		Dash
79	};
80	
81	namespace JamSim
82	{
83	inline constexpr int32 MechanicCount = 3;
84	} // namespace JamSim
85	
86	/** Who owns each mechanic. A steal is a change of owner here and nothing else. */
87	struct FJamLedger
88	{
89		EJamSide Owner[JamSim::MechanicCount] = { EJamSide::Hero, EJamSide::Hero, EJamSide::Hero };
90	
91		bool Has(EJamSide Side, EJamMechanic Mechanic) const { return Owner[static_cast<int32>(Mechanic)] == Side; }
92	};
93	
94	/**
95	 * State of each mechanic on a fighter. Both fighters carry all of them, so a mechanic that changes its owner needs no
96	 * copying: the new owner simply starts using his own state.
97	 */
98	struct FJamKatanaState
99	{
100		/** The strike of the series swung last, 1 to 3; 0 before the first one. */
101		int32 Strike = 0;
102		/** Step on which that strike lands. */
103		int32 HitTick = 0;
104		/** First step on which the next strike can start. */
105		int32 BusyUntilTick = 0;
106		/** Last step on which a press still continues the series. */
107		int32 ChainUntilTick = 0;
108		bool bHitPending = false;
109	};
110	
111	struct FJamShurikenState
112	{
113		int32 ReadyTick = 0;
114		/** Throws made so far: decides which one explodes. */
115		int32 Throws = 0;
116	};
117	
118	struct FJamDashState
119	{
120		FVector2D Dir = FVector2D::ZeroVector;
121		/** Distance covered per step while dashing. */
122		float StepLength = 0.f;
123		/** First step after the dash. */
124		int32 EndTick = 0;
125		/** First step on which damage is taken again. */
126		int32 InvulnerableUntilTick = 0;
127		int32 ReadyTick = 0;
128	};
129	
130	struct FJamFighter
131	{
132		FVector2D Pos = FVector2D::ZeroVector;
133		/** Position before the last step, for the view to interpolate from. */
134		FVector2D PrevPos = FVector2D::ZeroVector;
135		FVector2D Facing = FVector2D(1.0, 0.0);
136		float Radius = 0.f;
137		float Speed = 0.f;
138		float Health = 0.f;
139		float MaxHealth = 0.f;
140		/** First step on which the ball can be shot again. */
141		int32 BallReadyTick = 0;
142		FJamKatanaState Katana;
143		FJamShurikenState Shuriken;
144		FJamDashState Dash;
145	};
146	
147	enum class EJamProjectile : uint8
148	{
149		Ball,
150		Shuriken,
151		Memo
152	};
153	
154	struct FJamProjectile
155	{
156		int32 Id = 0;
157		EJamProjectile Kind = EJamProjectile::Ball;
158		EJamSide Owner = EJamSide::Hero;
159		FVector2D Pos = FVector2D::ZeroVector;
160		FVector2D PrevPos = FVector2D::ZeroVector;
161		FVector2D Vel = FVector2D::ZeroVector;
162		float Radius = 0.f;
163		float Damage = 0.f;
164		/** Step on which it disappears on its own. */
165		int32 DieTick = 0;
166		bool bExplosive = false;
167	};
168	
169	/** A place that will hurt: shown as a warning first, hits once at HitTick. */
