68		else if (!bHeld)
69		{
70			Delta = JamMoveRules::Velocity(Intent.Move, Self.Speed) * JamSim::StepDt;
71		}
72		// A fighter that stands is never nudged, whoever walks into it.
73		if (!Delta.IsNearlyZero())
74		{
75			JamFightOps::Shift(Fight, Side, Delta, Balance.ArenaRadius);
76		}
77	}
78	
79	void AdvanceProjectiles(FJamFight& Fight, const FHands& Hands)
80	{
81		for (int32 Index = Fight.Projectiles.Num() - 1; Index >= 0; --Index)
82		{
83			FJamProjectile& Flying = Fight.Projectiles[Index];
84			Flying.PrevPos = Flying.Pos;
85			Flying.Pos += Flying.Vel * JamSim::StepDt;
86			const EJamSide TargetSide = JamSim::Other(Flying.Owner);
87			const FJamFighter& Target = Fight.Fighters[TargetSide];
88			// A dashing fighter is not there for a projectile: it flies through him and on.
89			const bool bHit = !JamDashRules::IsInvulnerable(Target.Dash, Fight.Tick) &&
90				JamProjectileRules::SweepHitsCircle(Flying.PrevPos, Flying.Pos, Flying.Radius, Target.Pos, Target.Radius);
91			if (!bHit && !JamProjectileRules::IsGone(Flying, Fight.Tick, Hands.Hero.ArenaRadius))
92			{
93				continue;
94			}
95			const FJamProjectile Done = Flying;
96			Fight.Projectiles.RemoveAtSwap(Index);
97			if (Done.bExplosive)
98			{
99				JamShurikenRules::Explode(Fight, Done, Hands.Of(Done.Owner));
100			}
101			else if (bHit)
102			{
103				JamFightOps::Hurt(Fight, TargetSide, Done.Damage, Done.Pos, Done.Id);
104			}
105			else
106			{
107				JamFightOps::AddEvent(Fight, EJamEvent::ProjectileGone, Done.Owner, Done.Id, Done.Pos, 0.f);
108			}
109		}
110	}
111	
112	void ShootBall(FJamFight& Fight, EJamSide Side, const FJamBalanceData& Balance)
113	{
114		FJamFighter& Self = Fight.Fighters[Side];
115		if (Fight.Tick < Self.BallReadyTick)
116		{
117			return;
118		}
119		Self.BallReadyTick = Fight.Tick + JamSim::Ticks(Balance.BallCooldown);
120		FJamShot Ball;
121		Ball.Kind = EJamProjectile::Ball;
122		Ball.Speed = Balance.BallSpeed;
123		Ball.Radius = Balance.BallRadius;
124		Ball.Damage = Balance.BallDamage;
125		Ball.Life = Balance.BallLife;
126		JamFightOps::Shoot(Fight, Side, Self.Facing, Ball);
127	}
128	
129	/** A held button does whatever the fighter owns for it right now: the same code for the hero and for the boss. */
130	void UseButton(FJamFight& Fight, EJamSide Side, EJamButton Button, const FJamBalanceData& Balance)
131	{
132		switch (JamLoadoutRules::ActionFor(Button, Side, Fight.Ledger))
133		{
134			case EJamAction::Katana:
135				JamKatanaRules::Press(Fight, Side, Balance);
136				break;
137			case EJamAction::Shuriken:
138				JamShurikenRules::Throw(Fight, Side, Balance);
139				break;
140			case EJamAction::Ball:
141				ShootBall(Fight, Side, Balance);
142				break;
143			default:
144				break;
145		}
146	}
147	
148	void UseButtons(FJamFight& Fight, EJamSide Side, const FJamIntent& Intent, const FJamBalanceData& Balance)
149	{
150		if (IsHeld(Fight, Side))
151		{
152			return;
153		}
154		if (Intent.bPrimary)
155		{
156			UseButton(Fight, Side, EJamButton::Primary, Balance);
157		}
158		if (Intent.bSecondary)
159		{
160			UseButton(Fight, Side, EJamButton::Secondary, Balance);
161		}
162	}
163	
164	/** A step of the open card: the fighters stand, only the card's clock runs. */
165	void WaitForTheChoice(FJamFight& Fight, int32 Choice, const FJamBalanceData& Balance)
166	{
167		for (FJamFighter& Fighter : Fight.Fighters.Items)
168		{
169			Fighter.PrevPos = Fighter.Pos;
170		}
171		++Fight.Tick;
172		JamStealRules::Advance(Fight, Choice, Balance);
173	}
174	} // namespace
175	
176	FJamFight JamFightRules::Start(const FJamBalanceData& Balance, int32 Seed)
177	{
178		FJamFight Fight;
179		Fight.Stream.Initialize(Seed);
180		Fight.Fighters[EJamSide::Hero] =
181			MakeFighter(Balance.ArenaRadius * HeroStartX, 1.f, Balance.HeroRadius, Balance.HeroSpeed, Balance.HeroHealth);
182		Fight.Fighters[EJamSide::Boss] =
183			MakeFighter(Balance.ArenaRadius * BossStartX, -1.f, Balance.BossRadius, Balance.BossSpeed, Balance.BossHealth);
184		// The boss waits a moment before his first move: the player gets a look at the arena.
185		Fight.Boss.BusyUntilTick = JamSim::Ticks(Balance.BossRecovery);
186		Fight.Steal.Floor = JamStealRules::ThresholdHealth(0, Balance);
187		return Fight;
188	}
189	
190	void JamFightRules::Step(FJamFight& Fight, const FJamIntents& Intents, const FJamBalanceData& Balance)
191	{
192		Fight.Events.Reset();
193		if (Fight.Phase == EJamPhase::HeroDead || Fight.Phase == EJamPhase::Won)
194		{
195			// The fight is over: time stands still until somebody starts it again.
196			return;
197		}
198		if (Fight.Phase == EJamPhase::Steal)
199		{
200			WaitForTheChoice(Fight, Intents[EJamSide::Hero].Choice, Balance);
201			return;
202		}
203		const FHands Hands{ Balance, JamLoadoutRules::InHandsOf(EJamSide::Boss, Balance) };
204		for (const EJamSide Side : { EJamSide::Hero, EJamSide::Boss })
205		{
206			MoveFighter(Fight, Side, Intents[Side], Hands.Of(Side));
207		}
208		// Projectiles fly before new ones are shot, so a new one is first seen at the muzzle.
209		AdvanceProjectiles(Fight, Hands);
210		JamHazardRules::Advance(Fight);
211		for (const EJamSide Side : { EJamSide::Hero, EJamSide::Boss })
212		{
213			UseButtons(Fight, Side, Intents[Side], Hands.Of(Side));
214		}
215		JamBossRules::Act(Fight, Intents[EJamSide::Boss], Balance);
216		for (const EJamSide Side : { EJamSide::Hero, EJamSide::Boss })
217		{
218			JamKatanaRules::Land(Fight, Side, Hands.Of(Side));
219		}
220		JamOutcomeRules::Settle(Fight, Balance);
221		++Fight.Tick;
222	}
223	
224	void JamFightRules::Play(FJamFight& Fight, const FJamIntent& HeroIntent, const FJamBalanceData& Balance)
225	{
226		FJamIntents Intents;
227		Intents[EJamSide::Hero] = HeroIntent;
228		Intents[EJamSide::Boss] = JamBossRules::Decide(Fight, Balance);
229		Step(Fight, Intents, Balance);
