#include "Sim/JamLoadoutRules.h"

EJamAction JamLoadoutRules::ActionFor(EJamButton Button, EJamSide Side, const FJamLedger& Ledger)
{
	// Only the hero has the ball: it is what is left of him when a mechanic is gone.
	const EJamAction Fallback = Side == EJamSide::Hero ? EJamAction::Ball : EJamAction::None;
	switch (Button)
	{
		case EJamButton::Primary:
			return Ledger.Has(Side, EJamMechanic::Katana) ? EJamAction::Katana : Fallback;
		case EJamButton::Secondary:
			return Ledger.Has(Side, EJamMechanic::Shuriken) ? EJamAction::Shuriken : Fallback;
		default:
			return Ledger.Has(Side, EJamMechanic::Dash) ? EJamAction::Dash : EJamAction::None;
	}
}

void JamLoadoutRules::Give(FJamLedger& Ledger, EJamMechanic Mechanic, EJamSide NewOwner)
{
	Ledger.Owner[static_cast<int32>(Mechanic)] = NewOwner;
}

bool JamLoadoutRules::FirstOwned(const FJamLedger& Ledger, EJamSide Side, EJamMechanic& OutMechanic)
{
	for (int32 Index = 0; Index < JamSim::MechanicCount; ++Index)
	{
		if (Ledger.Owner[Index] == Side)
		{
			OutMechanic = static_cast<EJamMechanic>(Index);
			return true;
		}
	}
	return false;
}

TArray<EJamMechanic> JamLoadoutRules::Owned(const FJamLedger& Ledger, EJamSide Side)
{
	TArray<EJamMechanic> Result;
	for (int32 Index = 0; Index < JamSim::MechanicCount; ++Index)
	{
		if (Ledger.Owner[Index] == Side)
		{
			Result.Add(static_cast<EJamMechanic>(Index));
		}
	}
	return Result;
}

FJamBalanceData JamLoadoutRules::InHandsOf(EJamSide Side, const FJamBalanceData& Balance)
{
	FJamBalanceData Hands = Balance;
	if (Side == EJamSide::Boss)
	{
		Hands.KatanaWindUp = Balance.BossKatanaWindUp;
		Hands.KatanaDamage *= Balance.BossStolenDamage;
		Hands.KatanaFinisherDamage *= Balance.BossStolenDamage;
		Hands.ShurikenDamage *= Balance.BossStolenDamage;
		Hands.ShurikenExplosionDamage *= Balance.BossStolenDamage;
		Hands.ShurikenSpeed *= Balance.BossStolenSpeed;
		Hands.ShurikenCooldown *= Balance.BossStolenCooldown;
		Hands.DashCooldown *= Balance.BossStolenCooldown;
	}
	return Hands;
}

const TCHAR* JamLoadoutRules::Name(EJamMechanic Mechanic)
{
	switch (Mechanic)
	{
		case EJamMechanic::Katana:
			return TEXT("KATANA");
		case EJamMechanic::Shuriken:
			return TEXT("SHURIKEN");
		default:
			return TEXT("DASH");
	}
}
#pragma once

#include "Core/JamBalance.h"
#include "Core/JamTypes.h"
#include "CoreMinimal.h"

/** The buttons of a fighter that a mechanic can sit on. */
enum class EJamButton : uint8
{
	Primary,
	Secondary,
	Dash
};

/** What a button does this very moment. */
enum class EJamAction : uint8
{
	None,
	Ball,
	Katana,
	Shuriken,
	Dash
};

/**
 * Who can do what. Every mechanic has one owner; the hero's attack buttons fall back to the weak ball when their
 * mechanic is gone, the boss gets nothing he was not given.
 * Tests: Jam.Loadout.*
 */
namespace JamLoadoutRules
{
/** The action behind a button for a side with this ledger. */
JAMGAME_API EJamAction ActionFor(EJamButton Button, EJamSide Side, const FJamLedger& Ledger);

/** Moves one mechanic to a new owner. */
JAMGAME_API void Give(FJamLedger& Ledger, EJamMechanic Mechanic, EJamSide NewOwner);

/** The first mechanic the side owns, in the order of the enum. False when it owns none. */
JAMGAME_API bool FirstOwned(const FJamLedger& Ledger, EJamSide Side, EJamMechanic& OutMechanic);

/** Everything the side owns, in the order of the enum. */
JAMGAME_API TArray<EJamMechanic> Owned(const FJamLedger& Ledger, EJamSide Side);

/**
 * The balance numbers as a side holds them. The hero's are the numbers themselves; in the Publisher's hands a stolen
 * mechanic is weaker and slower, and his katana warns before it lands: the player must be able to read what he made.
 */
JAMGAME_API FJamBalanceData InHandsOf(EJamSide Side, const FJamBalanceData& Balance);

/** Name of a mechanic for the screen. */
JAMGAME_API const TCHAR* Name(EJamMechanic Mechanic);
} // namespace JamLoadoutRules
#include "Sim/JamDashRules.h"

FVector2D JamDashRules::Direction(const FVector2D& Move, const FVector2D& Facing)
{
	return Move.IsNearlyZero() ? Facing.GetSafeNormal() : Move.GetSafeNormal();
}

FJamDashState JamDashRules::Start(const FVector2D& Dir, int32 Tick, const FJamBalanceData& Balance)
{
	const int32 Steps = JamSim::Ticks(Balance.DashDuration);
	FJamDashState State;
	State.Dir = Dir;
	State.StepLength = Balance.DashDistance / Steps;
	State.EndTick = Tick + Steps;
	State.InvulnerableUntilTick = Tick + JamSim::Ticks(Balance.DashInvulnerable);
	// A cooldown shorter than the dash itself would start a dash inside a dash.
	State.ReadyTick = FMath::Max(State.EndTick, Tick + JamSim::Ticks(Balance.DashCooldown));
	return State;
}

bool JamDashRules::CanStart(const FJamDashState& State, int32 Tick)
{
	return Tick >= State.ReadyTick;
}

bool JamDashRules::IsDashing(const FJamDashState& State, int32 Tick)
{
	return Tick < State.EndTick;
}

bool JamDashRules::IsInvulnerable(const FJamDashState& State, int32 Tick)
{
	return Tick < State.InvulnerableUntilTick;
}
