	Ball.Kind = EJamProjectile::Ball;
	Ball.Speed = Balance.BallSpeed;
	Ball.Radius = Balance.BallRadius;
	Ball.Damage = Balance.BallDamage;
	Ball.Life = Balance.BallLife;
