	Projectile.Id = Fight.NextId++;
	Projectile.Kind = Shot.Kind;
	Projectile.Owner = Owner;
	Projectile.Pos = Projectile.PrevPos = Self.Pos + Dir * (Self.Radius + Shot.Radius);
	Projectile.Vel = Dir * Shot.Speed;
